// Secure application with security best practices implemented
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const { createLogger, transports, format } = require('winston');

const app = express();

// ========== SECURITY HEADERS ==========
app.use(helmet({
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));

// ========== HTTPS ENFORCEMENT ==========
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect('https://' + req.headers.host + req.url);
    }
    next();
  });
}

// ========== CORS CONFIGURATION ==========
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000'];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// ========== REQUEST SIZE LIMITS ==========
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========== CONTENT TYPE VALIDATION ==========
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.get('Content-Type');
    if (req.body && (!contentType || !contentType.includes('application/json'))) {
      return res.status(415).json({ error: 'Unsupported Media Type. Use application/json' });
    }
  }
  next();
});

// ========== LOGGING ==========
const logger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.json()
  ),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'combined.log' }),
    new transports.File({ filename: 'security.log', level: 'warn' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new transports.Console({
    format: format.simple()
  }));
}

app.use(morgan('combined', { stream: { write: message => logger.info(message.trim()) } }));

// ========== RATE LIMITING ==========
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip, path: req.path });
    res.status(429).json({ error: 'Too many requests' });
  }
});

const healthLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 30,
  message: { error: 'Too many health check requests' }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many authentication attempts, please try again later.' }
});

app.use(limiter);

// ========== INPUT VALIDATION MIDDLEWARE ==========
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { 
      errors: errors.array(), 
      ip: req.ip,
      path: req.path 
    });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ========== AUTHENTICATION MIDDLEWARE ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Missing authentication token', { ip: req.ip, path: req.path });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'default-secret-change-in-production');
    req.user = decoded;
    next();
  } catch (err) {
    logger.warn('Invalid authentication token', { 
      ip: req.ip, 
      path: req.path,
      error: err.message 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Optionally require specific roles
const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }
    if (!roles.includes(req.user.role)) {
      logger.warn('Insufficient permissions', { 
        user: req.user.userId, 
        requiredRoles: roles,
        ip: req.ip 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ========== SANITIZATION ==========
const sanitizeUserData = (user) => {
  const { id, name, email } = user;
  return { id, name, email };
};

// ========== ROUTES ==========

// Health check (rate limited)
app.get('/health', healthLimiter, (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Login endpoint (rate limited)
app.post('/auth/login',
  authLimiter,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }).trim()
  ],
  validateRequest,
  (req, res) => {
    // TODO: Implement actual authentication with bcrypt
    // For demo purposes, just return a token
    const token = jwt.sign(
      { userId: 1, email: req.body.email, role: 'user' },
      process.env.JWT_SECRET || 'default-secret-change-in-production',
      { expiresIn: '1h' }
    );

    logger.info('User logged in', { email: req.body.email, ip: req.ip });
    res.json({ token, expiresIn: '1h' });
  }
);

// Protected users endpoint
app.get('/users',
  authenticateToken,
  requireRole('admin', 'user'),
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt()
  ],
  validateRequest,
  (req, res) => {
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].map(sanitizeUserData);

    logger.info('Users accessed', { user: req.user.userId, ip: req.ip });
    res.json({
      data: users,
      pagination: { page, limit, total: users.length }
    });
  }
);

// Specific user endpoint
app.get('/users/:userId',
  authenticateToken,
  [
    query('userId').isInt({ min: 1 }).toInt()
  ],
  validateRequest,
  (req, res) => {
    const userId = parseInt(req.params.userId);

    // Users can only access their own data unless they're admins
    if (req.user.role !== 'admin' && req.user.userId !== userId) {
      logger.warn('Unauthorized user access attempt', {
        requester: req.user.userId,
        target: userId,
        ip: req.ip
      });
      return res.status(403).json({ error: 'Access denied' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: sanitizeUserData(user) });
  }
);

// ========== ERROR HANDLING ==========
app.use((err, req, res, next) => {
  logger.error('Error occurred', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', { path: req.path, method: req.method, ip: req.ip });
  res.status(404).json({ error: 'Not Found' });
});

// ========== START SERVER ==========
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

