### Phase 2: Implement Secrets Manager (Production-Ready)

#### Option A: AWS Secrets Manager

```bash
npm install @aws-sdk/client-secrets-manager
```

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretsCache = {};

async function getSecret(secretName) {
  // Cache secrets to avoid repeated API calls
  if (secretsCache[secretName] && !isCacheExpired(secretsCache[secretName])) {
    return secretsCache[secretName].value;
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    const secret = response.SecretString
      ? JSON.parse(response.SecretString)
      : response.SecretBinary;

    // Cache for 5 minutes
    secretsCache[secretName] = {
      value: secret,
      expiresAt: Date.now() + 5 * 60 * 1000
    };

    return secret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
}

async function loadSecrets() {
  try {
    const dbSecrets = await getSecret('prod/database/credentials');
    const apiSecrets = await getSecret('prod/api/keys');
    const jwtSecret = await getSecret('prod/jwt/secret');

    return {
      database: dbSecrets,
      api: apiSecrets,
      jwt: jwtSecret
    };
  } catch (error) {
    console.error('Failed to load secrets from Secrets Manager:', error);
    // Fallback to environment variables for local development
    return {
      database: {
        url: process.env.DATABASE_URL
      },
      api: {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY
      },
      jwt: {
        secret: process.env.JWT_SECRET
      }
    };
  }
}

module.exports = { getSecret, loadSecrets };
```

Usage in application:

```javascript
const { loadSecrets } = require('./config/secrets');

async function startServer() {
  const secrets = await loadSecrets();

  const app = express();

  // Use secrets from secrets manager
  app.set('jwt-secret', secrets.jwt.secret);
  app.set('db-url', secrets.database.url);

  app.listen(3000);
}

startServer();
```

