## Complete Secure Implementation

Create `config/secrets-manager.js`:

```javascript
require('dotenv').config();

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Only use secrets manager in production/staging
const USE_SECRETS_MANAGER = ['production', 'staging'].includes(process.env.NODE_ENV);

class SecretsManager {
  constructor() {
    this.client = USE_SECRETS_MANAGER ? new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    }) : null;

    this.cache = new Map();
    this.CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Development mode: use environment variables
    if (!USE_SECRETS_MANAGER) {
      return this.getFromEnv(secretName);
    }

    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.CACHE_TTL) {
      return cached.value;
    }

    // Fetch from AWS Secrets Manager
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString
        ? JSON.parse(response.SecretString)
        : Buffer.from(response.SecretBinary, 'base64').toString();

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[SecretsManager] Loaded secret: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[SecretsManager] Failed to load ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  getFromEnv(secretName) {
    const envMapping = {
      'prod/jwt/secret': process.env.JWT_SECRET,
      'prod/database/credentials': { url: process.env.DATABASE_URL },
      'prod/api/keys': {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      }
    };

    const secret = envMapping[secretName];
    if (!secret) {
      throw new Error(`Secret ${secretName} not found in environment`);
    }
    return secret;
  }

  invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = new SecretsManager();
```

