/**
 * Secrets Manager - Secure secrets loading from multiple sources
 * 
 * Priority order:
 * 1. AWS Secrets Manager (production/staging)
 * 2. Environment variables (development/local)
 * 
 * Never log actual secret values!
 */

require('dotenv').config();

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Configuration
const CONFIG = {
  USE_SECRETS_MANAGER: ['production', 'staging'].includes(process.env.NODE_ENV),
  AWS_REGION: process.env.AWS_REGION || 'us-east-1',
  CACHE_TTL: 5 * 60 * 1000, // 5 minutes
};

// Secret name mappings (AWS secret name -> local structure)
const SECRET_MAPPINGS = {
  'prod/app/jwt': 'jwt',
  'prod/app/database': 'database',
  'prod/app/api-keys': 'api',
};

// Validate required configuration
function validateConfig() {
  if (CONFIG.USE_SECRETS_MANAGER && !process.env.AWS_REGION) {
    console.warn('[SecretsManager] AWS_REGION not set, using default: us-east-1');
  }
}

/**
 * Secrets Manager Class
 */
class SecretsManager {
  constructor() {
    this.client = null;
    this.cache = new Map();
    this.initialized = false;

    // Initialize AWS client if needed
    if (CONFIG.USE_SECRETS_MANAGER) {
      try {
        this.client = new SecretsManagerClient({
          region: CONFIG.AWS_REGION,
          // Use default AWS credential chain (IAM roles, env vars, etc.)
        });
        console.log('[SecretsManager] Initialized with AWS Secrets Manager');
      } catch (error) {
        console.error('[SecretsManager] Failed to initialize AWS client:', error.message);
      }
    } else {
      console.log('[SecretsManager] Running in local mode (using environment variables)');
    }

    this.initialized = true;
  }

  /**
   * Get a secret by name
   * @param {string} secretName - The name of the secret
   * @returns {Promise<any>} The secret value
   */
  async getSecret(secretName) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized');
    }

    const startTime = Date.now();

    try {
      let secret;

      if (CONFIG.USE_SECRETS_MANAGER) {
        secret = await this.getFromAWS(secretName);
      } else {
        secret = await this.getFromEnv(secretName);
      }

      // Log access (without exposing values)
      const duration = Date.now() - startTime;
      this.logAccess(secretName, duration, true);

      return secret;
    } catch (error) {
      const duration = Date.now() - startTime;
      this.logAccess(secretName, duration, false, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<Object>} Object with all secrets
   */
  async getSecrets(secretNames) {
    const secrets = {};
    const errors = [];

    await Promise.all(
      secretNames.map(async (name) => {
        try {
          secrets[name] = await this.getSecret(name);
        } catch (error) {
          errors.push({ name, error: error.message });
        }
      })
    );

    if (errors.length > 0) {
      console.error('[SecretsManager] Failed to load some secrets:', errors);
    }

    return secrets;
  }

  /**
   * Get all application secrets
   * @returns {Promise<Object>} All application secrets
   */
  async getAllSecrets() {
    const secretNames = Object.keys(SECRET_MAPPINGS);
    const awsSecrets = await this.getSecrets(secretNames);

    // Transform to expected structure
    const secrets = {};
    for (const [awsName, localName] of Object.entries(SECRET_MAPPINGS)) {
      secrets[localName] = awsSecrets[awsName];
    }

    return secrets;
  }

  /**
   * Fetch secret from AWS Secrets Manager (with caching)
   * @private
   */
  async getFromAWS(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < CONFIG.CACHE_TTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else if (response.SecretBinary) {
        secret = JSON.parse(
          Buffer.from(response.SecretBinary, 'base64').toString()
        );
      } else {
        throw new Error(`Secret ${secretName} has no value`);
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      console.log(`[SecretsManager] Loaded secret from AWS: ${secretName}`);
      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      } else if (error.name === 'AccessDeniedException') {
        throw new Error(`Access denied to secret: ${secretName}`);
      }
      throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Fetch secret from environment variables
   * @private
   */
  async getFromEnv(secretName) {
    const envSecrets = {
      'prod/app/jwt': {
        secret: process.env.JWT_SECRET,
      },
      'prod/app/database': {
        url: process.env.DATABASE_URL,
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        name: process.env.DB_NAME,
        user: process.env.DB_USER,
        password: process.env.DB_PASSWORD,
      },
      'prod/app/api-keys': {
        anthropic: process.env.ANTHROPIC_API_KEY,
        stripe: process.env.STRIPE_SECRET_KEY,
        logfire: process.env.LOGFIRE_TOKEN,
      },
    };

    const secret = envSecrets[secretName];
    if (!secret) {
      throw new Error(`Secret ${secretName} not found in environment variables`);
    }

    // Validate that required fields are present
    this.validateSecret(secretName, secret);

    console.log(`[SecretsManager] Loaded secret from env: ${secretName}`);
    return secret;
  }

  /**
   * Validate that a secret has required fields
   * @private
   */
  validateSecret(secretName, secret) {
    const validations = {
      'prod/app/jwt': (s) => s.secret && s.secret.length >= 32,
      'prod/app/database': (s) => s.url || (s.host && s.name),
      'prod/app/api-keys': () => true, // Optional keys
    };

    const validator = validations[secretName];
    if (validator && !validator(secret)) {
      throw new Error(`Secret ${secretName} failed validation`);
    }
  }

  /**
   * Log secret access (for audit trail)
   * @private
   */
  logAccess(secretName, duration, success, error = null) {
    const logData = {
      timestamp: new Date().toISOString(),
      secretName: this.maskSecretName(secretName),
      duration: `${duration}ms`,
      success,
      source: CONFIG.USE_SECRETS_MANAGER ? 'aws' : 'env',
    };

    if (error) {
      logData.error = error;
    }

    console.log('[SecretsManager] Access:', JSON.stringify(logData));
  }

  /**
   * Mask secret name for logging (hide sensitive parts)
   * @private
   */
  maskSecretName(secretName) {
    return secretName.replace(/\/prod\//, '/***/');
  }

  /**
   * Invalidate cache (call when secrets are rotated)
   * @param {string} [secretName] - Specific secret to invalidate, or all if not specified
   */
  invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`[SecretsManager] Cache invalidated for: ${this.maskSecretName(secretName)}`);
    } else {
      this.cache.clear();
      console.log('[SecretsManager] All cache invalidated');
    }
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    const entries = Array.from(this.cache.entries()).map(([name, data]) => ({
      name: this.maskSecretName(name),
      age: Date.now() - data.timestamp,
    }));

    return {
      size: this.cache.size,
      entries,
    };
  }
}

// Create singleton instance
const secretsManager = new SecretsManager();

/**
 * Express middleware to load secrets
 */
function secretsMiddleware(req, res, next) {
  secretsManager.getAllSecrets()
    .then(secrets => {
      req.secrets = secrets;
      next();
    })
    .catch(error => {
      console.error('[SecretsManager] Failed to load secrets:', error.message);
      res.status(500).json({ error: 'Configuration error' });
    });
}

