#!/usr/bin/env node

/**
 * Secret Scanner - Detect potential secrets in codebase
 * Run: node scripts/scan-for-secrets.js
 */

const fs = require('fs');
const path = require('path');

// Patterns that might indicate secrets
const SECRET_PATTERNS = [
  // API Keys
  { name: 'AWS Access Key', pattern: /AKIA[0-9A-Z]{16}/g, severity: 'critical' },
  { name: 'AWS Secret Key', pattern: /[0-9a-zA-Z/+]{40}/g, severity: 'critical' },
  { name: 'Stripe Key', pattern: /sk_(live|test)_[0-9a-zA-Z]{24,}/g, severity: 'critical' },
  { name: 'GitHub Token', pattern: /ghp_[a-zA-Z0-9]{36}/g, severity: 'critical' },
  { name: 'Generic API Key', pattern: /api[_-]?key\s*[:=]\s*['"]?[a-zA-Z0-9_\-]{20,}/gi, severity: 'high' },

  // Database
  { name: 'Database URL', pattern: /(postgres|mysql|mongodb):\/\/[^@\s]+:[^@\s]+@/g, severity: 'critical' },
  { name: 'DB Password', pattern: /(password|passwd|pwd)\s*[:=]\s*['"]?[^'"\s]{8,}/gi, severity: 'high' },

  // JWT
  { name: 'JWT Secret', pattern: /jwt[_-]?secret\s*[:=]\s*['"][^'"]{20,}['"]/gi, severity: 'high' },

  // Other
  { name: 'Private Key', pattern: /-----BEGIN (RSA )?PRIVATE KEY-----/g, severity: 'critical' },
  { name: 'Auth Token', pattern: /(auth[_-]?token|bearer)\s*[:=]\s*['"]?[a-zA-Z0-9_\-]{20,}/gi, severity: 'medium' },
];

// File extensions to scan
const SCAN_EXTENSIONS = ['.js', '.json', '.env', '.env.*', '.md', '.yml', '.yaml', '.txt'];

// Directories/files to ignore
const IGNORE_PATHS = [
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.env.example',
  'scripts/scan-for-secrets.js',
  'app.secure.js',
];

// Results storage
const results = {
  critical: [],
  high: [],
  medium: [],
  low: [],
};

/**
 * Check if a path should be ignored
 */
function shouldIgnore(filePath) {
  return IGNORE_PATHS.some(ignorePath => 
    filePath.includes(ignorePath) || filePath.startsWith(ignorePath)
  );
}

/**
 * Scan a single file for secrets
 */
function scanFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const relativePath = path.relative(process.cwd(), filePath);

    SECRET_PATTERNS.forEach(({ name, pattern, severity }) => {
      const matches = content.match(pattern);
      if (matches) {
        matches.forEach(match => {
          // Get line number
          const lines = content.split('\n');
          let lineNumber = 0;
          for (let i = 0; i < lines.length; i++) {
            if (lines[i].includes(match)) {
              lineNumber = i + 1;
              break;
            }
          }

          // Mask sensitive parts for display
          const maskedMatch = match.length > 20 
            ? match.substring(0, 8) + '...' + match.substring(match.length - 8)
            : match;

          results[severity].push({
            file: relativePath,
            line: lineNumber,
            type: name,
            match: maskedMatch,
            fullMatch: match,
          });
        });
      }
    });
  } catch (error) {
    // Skip files that can't be read
  }
}

/**
 * Recursively scan a directory
 */
function scanDirectory(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (shouldIgnore(fullPath)) {
      continue;
    }

    if (entry.isDirectory()) {
      scanDirectory(fullPath);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name);
      const nameMatches = SCAN_EXTENSIONS.some(e => 
        ext === e || entry.name.endsWith(e.replace('*', ''))
      );

      if (nameMatches || entry.name.startsWith('.env')) {
        scanFile(fullPath);
      }
    }
  }
}

/**
 * Print scan results
 */
function printResults() {
  console.log('\n' + '='.repeat(70));
  console.log('🔍 SECRET SCAN RESULTS');
  console.log('='.repeat(70) + '\n');

  const totalIssues = Object.values(results).reduce((sum, r) => sum + r.length, 0);

  if (totalIssues === 0) {
    console.log('✅ No secrets detected!\n');
    return 0;
  }

  // Print by severity
  const severityOrder = ['critical', 'high', 'medium', 'low'];
  const severityIcons = {
    critical: '🔴',
    high: '🟠',
    medium: '🟡',
    low: '🔵',
  };

  severityOrder.forEach(severity => {
    const issues = results[severity];
    if (issues.length > 0) {
      console.log(`${severityIcons[severity]} ${severity.toUpperCase()} (${issues.length} found):`);
      console.log('-'.repeat(70));

      // Group by file
      const byFile = {};
      issues.forEach(issue => {
        if (!byFile[issue.file]) {
          byFile[issue.file] = [];
        }
        byFile[issue.file].push(issue);
      });

      Object.entries(byFile).forEach(([file, fileIssues]) => {
        console.log(`\n  📄 ${file}`);
        fileIssues.forEach(issue => {
          console.log(`     Line ${issue.line}: ${issue.type}`);
          console.log(`     Found: "${issue.match}"`);
        });
      });

      console.log('');
    }
  });

  // Summary
  console.log('='.repeat(70));
  console.log('SUMMARY:');
  console.log(`  Critical: ${results.critical.length}`);
  console.log(`  High:     ${results.high.length}`);
  console.log(`  Medium:   ${results.medium.length}`);
  console.log(`  Low:      ${results.low.length}`);
  console.log(`  Total:    ${totalIssues}`);
  console.log('='.repeat(70));

  // Recommendations
  if (results.critical.length > 0 || results.high.length > 0) {
    console.log('\n🚨 IMMEDIATE ACTION REQUIRED:\n');
    console.log('1. Replace exposed secrets with new values');
    console.log('2. Add files to .gitignore');
    console.log('3. Remove secrets from git history:');
    console.log('   git filter-branch --force --index-filter \\');
    console.log('   "git rm --cached --ignore-unmatch <file>" --prune-empty --tag-name-filter cat -- --all');
    console.log('4. Force push: git push origin --force --all');
    console.log('5. Rotate all exposed credentials');
    console.log('');
  }

  return results.critical.length > 0 || results.high.length > 0 ? 1 : 0;
}

// Main execution
console.log('Scanning for secrets...\n');

try {
  scanDirectory(process.cwd());
  const exitCode = printResults();
  process.exit(exitCode);
} catch (error) {
  console.error('Error during scan:', error.message);
  process.exit(1);
}

