/**
 * Secure Secrets Manager Module
 * Handles loading secrets from multiple sources with proper fallback
 */

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get a secret with caching and automatic refresh
   * Priority: Secrets Manager > Environment Variables > Default Value
   */
  async getSecret(key, options = {}) {
    const { defaultValue, required = false, source = 'auto' } = options;

    // Check cache first
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    let value;

    // Try multiple sources in priority order
    switch (source) {
      case 'aws':
        value = await this.getFromAWS(key);
        break;
      case 'vault':
        value = await this.getFromVault(key);
        break;
      case 'auto':
      default:
        // Try AWS first, then fallback to env
        value = await this.getFromAWS(key) 
               || process.env[key] 
               || defaultValue;
    }

    // Handle missing required secrets
    if (value === undefined && required) {
      throw new Error(`❌ Required secret not found: ${key}`);
    }

    // Cache the result
    if (value !== undefined) {
      this.cache.set(key, {
        value: value,
        timestamp: Date.now()
      });
    }

    return value;
  }

  /**
   * Fetch secret from AWS Secrets Manager
   */
  async getFromAWS(key) {
    try {
      const AWS = require('aws-sdk');

      // Only initialize if AWS credentials are available
      if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
        return null;
      }

      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      // Map app key to AWS secret name
      const secretName = this.mapToAWSSecretName(key);

      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      if (data.SecretString) {
        const parsed = JSON.parse(data.SecretString);
        return parsed[key] || parsed.secret;
      }

      return data.SecretBinary;
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        return null; // Secret doesn't exist in AWS
      }
      console.warn(`⚠️  Failed to fetch secret from AWS: ${key}`, error.message);
      return null;
    }
  }

  /**
   * Fetch secret from HashiCorp Vault
   */
  async getFromVault(key) {
    try {
      const axios = require('axios');
      const vaultAddr = process.env.VAULT_ADDR;
      const vaultToken = process.env.VAULT_TOKEN;

      if (!vaultAddr || !vaultToken) {
        return null;
      }

      const response = await axios.get(
        `${vaultAddr}/v1/secret/data/${key}`,
        {
          headers: { 'X-Vault-Token': vaultToken },
          timeout: 5000
        }
      );

      return response.data.data.data.value;
    } catch (error) {
      if (error.response?.status === 404) {
        return null; // Secret doesn't exist in Vault
      }
      console.warn(`⚠️  Failed to fetch secret from Vault: ${key}`, error.message);
      return null;
    }
  }

  /**
   * Map application key to AWS secret name
   */
  mapToAWSSecretName(key) {
    const prefix = process.env.AWS_SECRET_PREFIX || 'myapp/';

    const keyMapping = {
      'DATABASE_URL': `${prefix}database-url`,
      'DATABASE_PASSWORD': `${prefix}database-password`,
      'AWS_ACCESS_KEY_ID': `${prefix}aws-access-key`,
      'AWS_SECRET_ACCESS_KEY': `${prefix}aws-secret-key`,
      'STRIPE_SECRET_KEY': `${prefix}stripe-key`,
      'ANTHROPIC_API_KEY': `${prefix}anthropic-key`,
      'SESSION_SECRET': `${prefix}session-secret`
    };

    return keyMapping[key] || `${prefix}${key.toLowerCase()}`;
  }

  /**
   * Clear cache (useful for testing or secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get all configuration securely
   */
  async getAllConfig() {
    const isProduction = process.env.NODE_ENV === 'production';

    return {
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT, 10) || 3000,

      // Database configuration
      database: {
        url: await this.getSecret('DATABASE_URL', { 
          required: isProduction,
          defaultValue: 'postgresql://localhost:5432/myapp'
        }),
        // Alternative: separate credentials
        host: process.env.DB_HOST || 'localhost',
        port: parseInt(process.env.DB_PORT, 10) || 5432,
        name: process.env.DB_NAME || 'myapp',
        user: process.env.DB_USER || 'postgres',
        password: await this.getSecret('DATABASE_PASSWORD', { 
          required: isProduction 
        })
      },

      // AWS configuration
      aws: {
        accessKeyId: await this.getSecret('AWS_ACCESS_KEY_ID'),
        secretAccessKey: await this.getSecret('AWS_SECRET_ACCESS_KEY'),
        region: process.env.AWS_REGION || 'us-east-1'
      },

      // Third-party services
      services: {
        stripe: {
          secretKey: await this.getSecret('STRIPE_SECRET_KEY', {
            required: isProduction
          }),
          publishableKey: process.env.STRIPE_PUBLISHABLE_KEY
        },
        anthropic: {
          apiKey: await this.getSecret('ANTHROPIC_API_KEY')
        }
      },

      // Security
      security: {
        sessionSecret: await this.getSecret('SESSION_SECRET', {
          required: isProduction
        }),
        jwtSecret: await this.getSecret('JWT_SECRET', {
          required: isProduction
        })
      }
    };
  }
}

