/**
 * Application Configuration
 * Loads configuration securely from multiple sources
 */

const secretsManager = require('./secrets');

let cachedConfig = null;

/**
 * Load application configuration
 * This should be called once at application startup
 */
async function loadConfig() {
  if (cachedConfig) {
    return cachedConfig;
  }

  console.log('🔐 Loading secure configuration...');

  try {
    const config = await secretsManager.getAllConfig();

    // Validate critical configuration
    validateConfig(config);

    cachedConfig = config;

    console.log('✅ Configuration loaded successfully');

    // Log NON-SENSITIVE config in development
    if (config.env !== 'production') {
      console.log('📝 Configuration:', {
        env: config.env,
        port: config.port,
        database: {
          host: config.database.host,
          port: config.database.port,
          name: config.database.name
          // NEVER log password or full URL
        },
        aws: {
          region: config.aws.region
          // NEVER log access keys
        }
      });
    }

    return config;
  } catch (error) {
    console.error('❌ Failed to load configuration:', error.message);
    throw error;
  }
}

/**
 * Validate required configuration
 */
function validateConfig(config) {
  const errors = [];

  // Environment-specific validation
  if (config.env === 'production') {
    if (!config.security.sessionSecret) {
      errors.push('SESSION_SECRET is required in production');
    }
    if (!config.database.url && !config.database.password) {
      errors.push('Database credentials required in production');
    }
  }

  // Database validation
  if (config.env === 'production' && config.database.host === 'localhost') {
    errors.push('Database host should not be localhost in production');
  }

  if (config.env === 'production' && config.database.name === 'myapp') {
    errors.push('Database name should be specific (not default "myapp") in production');
  }

  if (errors.length > 0) {
    throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
  }
}

/**
 * Get a specific configuration value (cached)
 */
function get(path) {
  if (!cachedConfig) {
    throw new Error('Configuration not loaded. Call loadConfig() first.');
  }

  return getNestedValue(cachedConfig, path);
}

/**
 * Helper to get nested object values
 */
function getNestedValue(obj, path) {
  return path.split('.').reduce((acc, part) => acc?.[part], obj);
}

module.exports = {
  loadConfig,
  get
};

