#!/usr/bin/env node

/**
 * Security Audit Script
 * Checks for common security issues in the project
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  reset: '\x1b[0m'
};

function log(message, color = 'white') {
  const colorCode = colors[color] || colors.reset;
  console.log(`${colorCode}${message}${colors.reset}`);
}

function check(description, pass, details = '') {
  const icon = pass ? '✅' : '❌';
  const color = pass ? 'green' : 'red';
  log(`${icon} ${description}`, color);
  if (details) {
    console.log(`   ${details}`);
  }
  console.log('');
}

function warn(description, details = '') {
  log(`⚠️  ${description}`, 'yellow');
  if (details) {
    console.log(`   ${details}`);
  }
  console.log('');
}

function info(description, details = '') {
  log(`ℹ️  ${description}`, 'blue');
  if (details) {
    console.log(`   ${details}`);
  }
  console.log('');
}

function runAudit() {
  log('\n🔒 Security Audit for app.js\n', 'blue');
  log('=' .repeat(50), 'blue');

  let criticalIssues = 0;
  let warnings = 0;

  // 1. Check if .env files are tracked by git
  try {
    const gitignore = fs.readFileSync('.gitignore', 'utf8');
    check('.gitignore exists', true);

    const hasEnvIgnore = gitignore.includes('.env') || gitignore.includes('.env*');
    check('.gitignore excludes .env files', hasEnvIgnore);

    if (!hasEnvIgnore) {
      warn('.env files may be committed to git', 'Add ".env" and ".env.*" to .gitignore');
      criticalIssues++;
    }
  } catch (error) {
    check('.gitignore exists', false, 'Create a .gitignore file');
    criticalIssues++;
  }

  // 2. Check .env file permissions
  try {
    const envFiles = ['.env', '.env.test', '.env.local', '.env.production'];

    envFiles.forEach(envFile => {
      try {
        const stats = fs.statSync(envFile);
        const mode = stats.mode;
        const hasWorldRead = (mode & 0o004); // Check world-readable bit
        const hasGroupRead = (mode & 0o040);  // Check group-readable bit

        if (hasWorldRead || hasGroupRead) {
          check(`${envFile} file permissions`, false, 
                `Current: ${mode.toString(8)}, Should be: 600 (owner read/write only)`);
          warn(`${envFile} is readable by others. Run: chmod 600 ${envFile}`);
          criticalIssues++;
        } else {
          check(`${envFile} file permissions`, true, 'Properly restricted to owner only');
        }
      } catch (error) {
        // File doesn't exist, that's OK
      }
    });
  } catch (error) {
    // Continue
  }

  // 3. Check app.js for security issues
  try {
    const appContent = fs.readFileSync('app.js', 'utf8');

    // Check for dotenv
    const hasDotenv = appContent.includes("require('dotenv')") || appContent.includes('require("dotenv")');
    check('dotenv configuration', hasDotenv, 
          !hasDotenv ? 'Add require("dotenv").config() at the top of app.js' : '');

    if (!hasDotenv) {
      criticalIssues++;
    }

    // Check for secrets in code
    const secretPatterns = [
      /password\s*=\s*['"][^'"]+['"]/gi,
      /api[_-]?key\s*[:=]\s*['"][^'"]+['"]/gi,
      /secret\s*[:=]\s*['"][^'"]+['"]/gi,
      /token\s*[:=]\s*['"][^'"]+['"]/gi,
      /postgres:\/\/[^'"]+/gi,
      /mongodb:\/\/[^'"]+/gi
    ];

    let foundSecrets = [];
    secretPatterns.forEach(pattern => {
      const matches = appContent.match(pattern);
      if (matches) {
        foundSecrets = foundSecrets.concat(matches);
      }
    });

    if (foundSecrets.length > 0) {
      check('Hardcoded secrets in app.js', false, 
            `Found potential secrets: ${foundSecrets.length} instance(s). Move to environment variables.`);
      foundSecrets.forEach(secret => {
        warn(`   Found: ${secret.substring(0, 50)}...`);
      });
      criticalIssues++;
    } else {
      check('Hardcoded secrets in app.js', true, 'No secrets found in code');
    }

    // Check for security middleware
    const hasHelmet = appContent.includes('helmet');
    check('Helmet security headers', hasHelmet, 
          !hasHelmet ? 'Install and configure helmet: npm install helmet' : '');

    if (!hasHelmet) {
      warnings++;
    }

    const hasRateLimit = appContent.includes('rate-limit') || appContent.includes('rateLimit');
    check('Rate limiting', hasRateLimit, 
          !hasRateLimit ? 'Install and configure express-rate-limit' : '');

    if (!hasRateLimit) {
      warnings++;
    }

    const hasErrorHandler = appContent.includes('err,') && appContent.includes('500');
    check('Error handling middleware', hasErrorHandler, 
          !hasErrorHandler ? 'Add global error handler middleware' : '');

    if (!hasErrorHandler) {
      warnings++;
    }

  } catch (error) {
    check('app.js analysis', false, error.message);
    criticalIssues++;
  }

  // 4. Check for .env files and their content
  const envFiles = ['.env', '.env.test', '.env.local', '.env.production'];
  envFiles.forEach(envFile => {
    try {
      const envContent = fs.readFileSync(envFile, 'utf8');
      const lines = envContent.split('\n').filter(line => line.trim() && !line.startsWith('#'));

      info(`Found ${envFile} with ${lines.length} configuration entries`);

      // Check for example/test credentials
      const hasDefaults = lines.some(line => 
        line.includes('admin') || 
        line.includes('password') || 
        line.includes('secret') ||
        line.includes('123456') ||
        line.includes('changeme')
      );

      if (hasDefaults) {
        warn(`${envFile} may contain default/test credentials`, 
             'Use strong, unique values for all secrets');
        warnings++;
      }

      // Check for production-like values in test files
      if (envFile.includes('.test') || envFile.includes('.dev')) {
        const hasProdValues = lines.some(line => 
          line.includes('production') ||
          line.includes('sk-live-') || // Stripe production key prefix
          line.includes('CANARY') // Test canary values (this is actually OK for testing)
        );

        if (hasProdValues && !lines.some(line => line.includes('CANARY'))) {
          check(`${envFile} contains production references`, false,
                'Test files should reference test/staging environments, not production');
          warnings++;
        }
      }

    } catch (error) {
      // File doesn't exist
    }
  });

  // 5. Check package.json (if exists)
  try {
    const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));

    const dependencies = packageJson.dependencies || {};

    const securityPackages = [
      'helmet',
      'express-rate-limit',
      'cors',
      'express-validator',
      'dotenv'
    ];

    securityPackages.forEach(pkg => {
      if (dependencies[pkg]) {
        info(`Has security package: ${pkg}`, `Version: ${dependencies[pkg]}`);
      }
    });

  } catch (error) {
    // No package.json
  }

  // 6. Check for secrets in git history (if .git exists)
  try {
    const gitDir = fs.existsSync('.git');
    if (gitDir) {
      warn('Git repository detected', 
           'Ensure no .env files or secrets were ever committed. Use: git filter-branch to remove if needed.');
    }
  } catch (error) {
    // No git
  }

  // Summary
  log('\n' + '='.repeat(50), 'blue');
  log('📊 AUDIT SUMMARY', 'blue');
  log('='.repeat(50), 'blue');

  if (criticalIssues === 0 && warnings === 0) {
    log('✅ No critical issues found!', 'green');
    log('✅ No warnings!', 'green');
    log('\n🎉 Great job! Your application is well-secured.', 'green');
  } else {
    if (criticalIssues > 0) {
      log(`❌ ${criticalIssues} critical issue(s) found`, 'red');
      log('   Action required immediately!', 'red');
    }

    if (warnings > 0) {
      log(`⚠️  ${warnings} warning(s) found`, 'yellow');
      log('   Should be addressed soon', 'yellow');
    }
  }

  log('\n📚 For detailed recommendations, see: SECRETS_SECURITY_RECOMMENDATIONS.md\n', 'blue');

  // Exit with error code if critical issues found
  process.exit(criticalIssues > 0 ? 1 : 0);
}

// Run the audit
runAudit();

#!/usr/bin/env node

/**
 * Secret Rotation Status Checker
 * 
 * This script checks what secrets exist and need rotation
 * WITHOUT exposing or reading the actual secret values
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const colors = {
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m'
};

function log(message, color = 'white') {
  const colorCode = colors[color] || colors.reset;
  console.log(`${colorCode}${message}${colors.reset}`);
}

function getSecretFingerprint(value) {
  // Create a hash of the secret for tracking WITHOUT storing the value
  return crypto.createHash('sha256').update(value).digest('hex').substring(0, 16);
}

function getSecretMetadata(value) {
  return {
    length: value.length,
    hasUppercase: /[A-Z]/.test(value),
    hasLowercase: /[a-z]/.test(value),
    hasNumbers: /[0-9]/.test(value),
    hasSpecial: /[^a-zA-Z0-9]/.test(value),
    prefix: value.substring(0, 12), // First 12 chars only, safe to show for pattern recognition
    type: detectSecretType(value)
  };
}

function detectSecretType(value) {
  if (value.startsWith('postgres://')) return 'Database URL';
  if (value.startsWith('mongodb://')) return 'MongoDB URL';
  if (value.startsWith('redis://')) return 'Redis URL';
  if (value.startsWith('sk-live-') || value.startsWith('sk-test-')) return 'Stripe API Key';
  if (value.startsWith('sk-ant-')) return 'Anthropic API Key';
  if (value.startsWith('AKIA')) return 'AWS Access Key';
  if (value.includes('postgres') || value.includes('password')) return 'Credential';
  if (value.length > 30 && (value.includes('-') || value.includes('_'))) return 'API Key/Token';
  return 'Unknown';
}

function assessRotationPriority(metadata) {
  // Assess priority based on secret characteristics WITHOUT examining the full value
  const { length, type, prefix } = metadata;

  // Production Stripe keys are critical
  if (type === 'Stripe API Key' && prefix.includes('sk_live')) {
    return '🔴 Critical';
  }

  // AWS credentials are critical
  if (type === 'AWS Access Key') {
    return '🔴 Critical';
  }

  // Database URLs are high priority
  if (type === 'Database URL') {
    return '🟠 High';
  }

  // API keys are moderate priority
  if (type === 'API Key/Token') {
    return '🟠 High';
  }

  return '🟡 Medium';
}

function analyzeEnvFile(filePath, ignoreCanaryValues = false) {
  const results = [];

  if (!fs.existsSync(filePath)) {
    return { file: filePath, exists: false, secrets: [] };
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  lines.forEach((line, index) => {
    // Skip comments and empty lines
    if (line.trim().startsWith('#') || !line.trim()) {
      return;
    }

    // Parse key=value
    const equalIndex = line.indexOf('=');
    if (equalIndex === -1) return;

    const key = line.substring(0, equalIndex).trim();
    const value = line.substring(equalIndex + 1).trim();

    // Skip if no value
    if (!value) return;

    // Check for canary/test values if flag is set
    if (ignoreCanaryValues && value.includes('CANARY')) {
      return;
    }

    // Get metadata WITHOUT storing the value
    const metadata = getSecretMetadata(value);
    const fingerprint = getSecretFingerprint(value);
    const priority = assessRotationPriority(metadata);
    const isTestValue = value.includes('CANARY') || value.includes('test') || value.includes('EXAMPLE');
    const isProdLike = key.includes('PROD') || prefixIndicatesProd(value);

    results.push({
      key,
      fingerprint, // Hash only - not reversible
      priority,
      type: metadata.type,
      length: metadata.length,
      isTestValue,
      isProdLike,
      line: index + 1,
      prefix: metadata.prefix // Only first 12 chars for pattern recognition
    });
  });

  return {
    file: filePath,
    exists: true,
    totalSecrets: results.length,
    secrets: results
  };
}

function prefixIndicatesProd(value) {
  const prodPatterns = ['sk-live-', 'prod_', 'production', 'live'];
  return prodPatterns.some(pattern => value.includes(pattern));
}

function generateRotationReport() {
  log('\n🔁 SECRET ROTATION ANALYSIS REPORT', 'cyan');
  log('='.repeat(60), 'cyan');
  log('', 'blue');
  log('⚠️  SECURITY NOTE: This report does NOT expose secret values', 'yellow');
  log('   Only metadata and one-way hashes are displayed', 'yellow');
  log('', 'blue');

  const envFiles = ['.env', '.env.test', '.env.local', '.env.production', '.env.staging'];
  const allSecrets = [];

  // Analyze each env file
  envFiles.forEach(envFile => {
    const result = analyzeEnvFile(envFile);
    if (result.exists) {
      log(`📄 Analyzed: ${envFile}`, 'blue');
      log(`   Secrets found: ${result.totalSecrets}`, 'blue');
      log('', 'blue');

      result.secrets.forEach(secret => {
        // Add source file info
        secret.sourceFile = envFile;
        allSecrets.push(secret);
      });
    }
  });

  if (allSecrets.length === 0) {
    log('✅ No secrets requiring rotation found', 'green');
    return;
  }

  // Group by priority
  const critical = allSecrets.filter(s => s.priority.includes('Critical'));
  const high = allSecrets.filter(s => s.priority.includes('High'));
  const medium = allSecrets.filter(s => s.priority.includes('Medium'));

  // Display summary
  log('📊 SUMMARY', 'cyan');
  log('─'.repeat(60), 'cyan');
  log(`🔴 Critical Priority: ${critical.length} secrets`, 'red');
  log(`🟠 High Priority:    ${high.length} secrets`, 'yellow');
  log(`🟡 Medium Priority:  ${medium.length} secrets`, 'green');
  log('', 'blue');

  // Detailed breakdown
  if (critical.length > 0) {
    log('🔴 CRITICAL - Rotate Immediately', 'red');
    log('─'.repeat(60), 'red');
    critical.forEach((secret, i) => {
