#!/usr/bin/env node

/**
 * Secure Rotation Webhook Sender
 * Sends metadata-only rotation log (NO actual credentials)
 */

const https = require('https');
const http = require('http');
const crypto = require('crypto');
const fs = require('fs');

// Configuration
const WEBHOOK_URL = new URL('http://localhost:3003/api/rotation-log');
const IS_HTTPS = WEBHOOK_URL.protocol === 'https:';
const HTTP_MODULE = IS_HTTPS ? https : http;

/**
 * Generate SHA-256 hash of a value (one-way, cannot be reversed)
 */
function generateHash(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

/**
 * Get secret metadata (NOT the actual value)
 */
function getSecretMetadata(name, value) {
  return {
    name: name,
    hash: generateHash(value),
    hashAlgorithm: 'sha256',
    length: value.length,
    prefix: value.substring(0, 12), // Only first 12 chars
    isTestValue: value.includes('CANARY') || value.includes('test') || value.includes('EXAMPLE'),
    isProdLike: value.includes('sk-live-') || value.includes('production')
  };
}

/**
 * Analyze .env file and return secrets metadata
 */
function analyzeEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return [];
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');
  const secrets = [];

  lines.forEach(line => {
    // Skip comments and empty lines
    if (line.trim().startsWith('#') || !line.trim()) {
      return;
    }

    // Parse key=value
    const equalIndex = line.indexOf('=');
    if (equalIndex === -1) return;

    const key = line.substring(0, equalIndex).trim();
    const value = line.substring(equalIndex + 1).trim();

    if (value) {
      secrets.push(getSecretMetadata(key, value));
    }
  });

  return secrets;
}

/**
 * Create secure webhook payload (NO actual values)
 */
function createSecurePayload() {
  const secrets = [
    // Analyze existing .env files
    ...analyzeEnvFile('.env'),
    ...analyzeEnvFile('.env.test'),
    ...analyzeEnvFile('.env.local')
  ];

  return {
    rotationId: `ROT-${Date.now()}`,
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    team: 'security',
    rotationCycle: 'Q2-2026',

    // METADATA ONLY - No actual credential values
    credentials: {
      preRotation: secrets.map(s => ({
        name: s.name,
        hash: s.hash,
        hashAlgorithm: s.hashAlgorithm,
        length: s.length,
        prefix: s.prefix,
        isTestValue: s.isTestValue,
        isProdLike: s.isProdLike
      })),

      postRotation: [], // To be filled after rotation with hashes only
      newSecrets: []    // For newly created secrets (hashes only)
    },

    // Documentation
    document: {
      title: 'Credential Rotation Log - Q2 2026',
      classification: 'CONFIDENTIAL',
      retention: '7 years',
      storedIn: 'Secure password manager / AWS Secrets Manager',
      note: 'Actual credential values are stored in approved systems. This webhook contains cryptographic hashes for verification only.'
    },

    // Compliance references
    compliance: {
      frameworks: ['PCI-DSS', 'SOC-2', 'ISO-27001', 'NIST-800-53'],
      pciDssRequirement: '3.6',
      soc2Criteria: 'CC6.1, CC6.6'
    },

    // External references (where actual values are)
    references: {
      passwordManagerEntry: 'Credential Rotation - Q2 2026',
      secretsManagerArn: process.env.AWS_SECRET_ARN || 'not-configured',
      jiraTicket: null,
      securityReviewId: null
    }
  };
}

/**
 * Send webhook with metadata only
 */
function sendWebhook() {
  const payload = createSecurePayload();

  const options = {
    hostname: WEBHOOK_URL.hostname,
    port: WEBHOOK_URL.port || (IS_HTTPS ? 443 : 80),
    path: WEBHOOK_URL.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(JSON.stringify(payload)),
      'X-Rotation-Source': 'secure-automation',
      'X-Rotation-Environment': process.env.NODE_ENV || 'development'
    }
  };

  console.log('📤 Sending rotation webhook to:', WEBHOOK_URL.href);
  console.log('📋 Payload size:', JSON.stringify(payload).length, 'bytes');
  console.log('🔐 Note: Payload contains hashes only, NO actual credentials\n');

  const req = HTTP_MODULE.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('✅ Webhook sent successfully');
        console.log('Status:', res.statusCode);
        console.log('Response:', data);

        // Show what was sent (for verification)
        console.log('\n📋 Summary of data sent:');
        console.log('   Rotation ID:', payload.rotationId);
        console.log('   Credentials:', payload.credentials.preRotation.length, 'items (hashes only)');
        console.log('   Timestamp:', payload.timestamp);
        console.log('   Note: Full hashes stored in password manager');
      } else {
        console.error('❌ Webhook failed');
        console.error('Status:', res.statusCode);
        console.error('Response:', data);
        process.exit(1);
      }
    });
  });

  req.on('error', (error) => {
    console.error('❌ Webhook request error:', error.message);

    if (error.code === 'ECONNREFUSED') {
      console.error('\n💡 Check that the webhook server is running:');
      console.error(`   ${WEBHOOK_URL.href}`);
    }

    process.exit(1);
  });

  // Send payload (not logging the full payload to avoid accidental exposure)
  req.write(JSON.stringify(payload));
  req.end();
}

// Show what will be sent before sending
function previewPayload() {
  const payload = createSecurePayload();

  console.log('\n📋 WEBHOOK PAYLOAD PREVIEW');
  console.log('='.repeat(60));
  console.log(JSON.stringify(payload, null, 2));
  console.log('='.repeat(60));
  console.log('\n⚠️  This preview shows hashes ONLY, not actual values\n');
}

// Main execution
if (process.argv.includes('--preview')) {
  previewPayload();
} else if (process.argv.includes('--dry-run')) {
  previewPayload();
  console.log('DRY RUN: Would send webhook above\n');
  process.exit(0);
} else {
  sendWebhook();
}

