// Secure version of app.js with security best practices implemented
// Addressing OWASP Top 10 vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');
const { body, query, param, validationResult } = require('express-validator');
const session = require('express-session');
const passport = require('passport');
const LocalStrategy = require('passport-local').Strategy;
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================
// A04: Security Headers (Helmet)
// ============================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// ============================================
// A03: Injection Prevention & Request Limits
// ============================================
// Prevent NoSQL injection
app.use(mongoSanitize());
// Prevent XSS
app.use(xss());

// Limit request size to prevent DoS
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// ============================================
// A01: Rate Limiting (Brute Force Protection)
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logSecurityEvent('RATE_LIMIT_EXCEEDED', {
      ip: req.ip,
      path: req.path
    });
    res.status(429).json({ error: 'Too many requests' });
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth endpoints
  skipSuccessfulRequests: true
});

app.use(limiter);

// ============================================
// A09: Security Logging
// ============================================
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    ...(process.env.NODE_ENV !== 'production' 
      ? [new winston.transports.Console()] 
      : [])
  ]
});

const logSecurityEvent = (event, details = {}) => {
  securityLogger.info({
    type: 'SECURITY_EVENT',
    event,
    timestamp: new Date().toISOString(),
    ...details
  });
};

// HTTP request logging
app.use(morgan('combined'));

// Request ID tracking
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============================================
// CORS Configuration
// ============================================
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// ============================================
// A07: Session & Authentication
// ============================================
app.use(session({
  secret: process.env.SESSION_SECRET || 'change-this-secret',
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    maxAge: 3600000, // 1 hour
    sameSite: 'strict'
  },
  name: 'appSessionId'
}));

app.use(passport.initialize());
app.use(passport.session());

// JWT Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('AUTH_TOKEN_MISSING', { 
      ip: req.ip, 
      path: req.path 
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    logSecurityEvent('AUTH_TOKEN_INVALID', { 
      ip: req.ip, 
      path: req.path,
      error: err.message 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Role-based authorization middleware
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    if (!roles.includes(req.user.role)) {
      logSecurityEvent('AUTHORIZATION_FAILED', {
        userId: req.user.id,
        requiredRoles: roles,
        userRole: req.user.role,
        path: req.path
      });
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
};

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// ============================================
// A02: HTTPS Enforcement (Production)
// ============================================
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect(301, 'https://' + req.headers.host + req.url);
    }
    next();
  });
}

// ============================================
// A08: Error Handling
// ============================================
// Health check endpoint (no authentication)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    // Only include timestamp in non-production
    ...(process.env.NODE_ENV !== 'production' && {
      timestamp: new Date().toISOString()
    })
  });
});

// Login endpoint with rate limiting
app.post('/login', 
  authLimiter,
  [
    body('username').trim().isLength({ min: 3, max: 50 }),
    body('password').isLength({ min: 8 })
  ],
  validateRequest,
  async (req, res) => {
    const { username, password } = req.body;

    try {
      // In a real app, fetch user from database
      const user = await getUserByUsername(username);

      if (!user) {
        logSecurityEvent('LOGIN_FAILED', { 
          username, 
          reason: 'User not found',
          ip: req.ip 
        });
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const isValidPassword = await bcrypt.compare(password, user.passwordHash);

      if (!isValidPassword) {
        logSecurityEvent('LOGIN_FAILED', { 
          userId: user.id, 
          reason: 'Invalid password',
          ip: req.ip 
        });
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      // Generate JWT token
      const token = jwt.sign(
        { 
          id: user.id, 
          username: user.username, 
          role: user.role 
        },
        process.env.JWT_SECRET,
        { expiresIn: '1h' }
      );

      logSecurityEvent('LOGIN_SUCCESS', { 
        userId: user.id, 
        ip: req.ip 
      });

      res.json({ 
        token,
        user: { id: user.id, username: user.username }
      });

    } catch (err) {
      logSecurityEvent('LOGIN_ERROR', { error: err.message });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Mock user database function (replace with actual DB)
const getUserByUsername = async (username) => {
  // In real app, query database
  if (username === 'admin') {
    return {
      id: 1,
      username: 'admin',
