        Name: `/app/${process.env.NODE_ENV}/${name}`,
        WithDecryption: true
      }));

      const value = result.Parameter.Value;
      this.cache.set(cacheKey, { value, timestamp: Date.now() });

      // Audit log secret access
      console.log(`📋 Secret accessed: ${name}`);

      return value;
    } catch (err) {
