/**
 * Secure Environment Configuration Module
 * 
 * This module handles secure loading and validation of environment variables
 * and secrets. It prevents the application from starting with missing secrets
 * in production and provides safe fallbacks for development.
 * 
 * SECURITY FEATURES:
 * - Validates required secrets on load
 * - Prevents hardcoded fallbacks in production
 * - Validates secret entropy (length, complexity)
 * - Sanitizes sensitive values from logs
 * - Type conversion helpers
 */

const dotenv = require('dotenv');
const path = require('path');
const crypto = require('crypto');

// ========================================
// Load environment files based on NODE_ENV
// ========================================
const env = process.env.NODE_ENV || 'development';

// Mapping of environment to .env file
const envFiles = {
  production: '.env.production',
  staging: '.env.staging',
  test: '.env.test',
  development: '.env.development'
};

// Try to load the appropriate .env file (silent fail for prod)
const envFilePath = path.resolve(process.cwd(), envFiles[env] || '.env');
dotenv.config({ path: envFilePath });
// Also load .env.local if it exists (should be .gitignored)
dotenv.config({ path: path.resolve(process.cwd(), '.env.local') });

// ========================================
// Secret Validation Utilities
// ========================================

/**
 * Checks if a string has sufficient entropy for cryptographic use
 * @param {string} value - The secret to check
 * @param {number} minLength - Minimum length requirement
 * @returns {boolean}
 */
const hasSufficientEntropy = (value, minLength = 32) => {
  if (!value || typeof value !== 'string') return false;
  if (value.length < minLength) return false;

  // Check for character variety
  const hasLower = /[a-z]/.test(value);
  const hasUpper = /[A-Z]/.test(value);
  const hasNumbers = /[0-9]/.test(value);
  const hasSpecial = /[^a-zA-Z0-9]/.test(value);

  const varietyTypes = [hasLower, hasUpper, hasNumbers, hasSpecial].filter(Boolean).length;
  return varietyTypes >= 3;
};

/**
 * Sanitizes a value for logging (hides secrets)
 * @param {string} key - The environment variable name
 * @param {string} value - The value (will be hidden)
 * @returns {string}
 */
const sanitizeForLog = (key, value) => {
  const secretKeys = [
    'SECRET', 'PASSWORD', 'KEY', 'TOKEN', 'PRIVATE',
    'DATABASE_URL', 'AWS_', 'STRIPE_', 'API_KEY',
    'CREDENTIALS', 'SESSION', 'JWT'
  ];

  const isSecret = secretKeys.some(secretKey => 
    key.toUpperCase().includes(secretKey)
  );

  if (!isSecret || !value) return value;

  // Show first 3 and last 3 characters for debugging
  if (value.length <= 8) {
    return `${value[0]}*${value.slice(-1)}`;
  }
  return `${value.slice(0, 3)}...${value.slice(-3)}`;
};

// ========================================
// Type Conversion Helpers
// ========================================

const getBoolean = (key, defaultValue = false) => {
  const value = process.env[key];
  if (value === undefined) return defaultValue;
  return value === 'true' || value === '1' || value === 'yes';
};

const getInt = (key, defaultValue = 0) => {
  const value = process.env[key];
  const parsed = parseInt(value, 10);
  return isNaN(parsed) ? defaultValue : parsed;
};

const getArray = (key, delimiter = ',') => {
  const value = process.env[key];
  if (!value) return [];
  return value.split(delimiter).map(v => v.trim()).filter(Boolean);
};

const getUrl = (key, defaultValue = null) => {
  const value = process.env[key];
  if (!value) return defaultValue;

  try {
    return new URL(value);
  } catch (err) {
    if (env === 'production') {
      throw new Error(`Invalid URL format for ${key}: ${value}`);
    }
    console.warn(`⚠️  Invalid URL for ${key}, using default`);
    return defaultValue;
  }
};

// ========================================
// Required Secrets (Must be present in production)
// ========================================

const REQUIRED_SECRETS = [
  'JWT_SECRET',
  'SESSION_SECRET',
  'DATABASE_URL'
];

const PRODUCTION_REQUIRED_SECRETS = [
  ...REQUIRED_SECRETS,
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// ========================================
// Secrets Validation
// ========================================

const validateSecrets = () => {
  const isProduction = env === 'production';
  const required = isProduction ? PRODUCTION_REQUIRED_SECRETS : REQUIRED_SECRETS;
  const missing = [];
  const weak = [];

  console.log(`\n🔐 Validating secrets for environment: ${env}`);

  // Check for missing secrets
  required.forEach(secret => {
    const value = process.env[secret];
    if (!value) {
      missing.push(secret);
    } else {
      // Check entropy for secret fields
      if (secret.includes('SECRET') || secret.includes('KEY') || secret.includes('TOKEN')) {
        const safe = hasSufficientEntropy(value, secret.includes('JWT') ? 32 : 24);
        if (!safe) {
          weak.push(secret);
        }
      }
    }
  });

  // Report missing secrets
  if (missing.length > 0) {
    console.error('\n❌ Missing required secrets:');
    missing.forEach(secret => {
      console.error(`   - ${secret}`);
    });

    if (isProduction) {
      console.error('\n🚨 CANNOT START PRODUCTION WITHOUT ALL SECRETS!');
      process.exit(1);
    } else {
      console.warn('\n⚠️  Development mode: continuing with missing secrets');
      console.warn('   Some features may not work correctly\n');
    }
  } else {
    console.log('✅ All required secrets present');
  }

  // Report weak secrets
  if (weak.length > 0) {
    console.warn('\n⚠️  Secrets with insufficient entropy (weak security):');
    weak.forEach(secret => {
      const value = process.env[secret];
      console.warn(`   - ${secret} (length: ${value?.length || 0})`);
    });
    console.warn('   Consider regenerating with stronger values\n');
  }

  // Log loaded secrets (sanitized) for visibility
  const envKeys = Object.keys(process.env)
    .filter(key => [
      'NODE_ENV', 'PORT', 'JWT_SECRET', 'SESSION_SECRET',
      'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN',
      'ALLOWED_ORIGINS'
    ].includes(key));

  if (!isProduction) {
    console.log('\n📋 Environment configuration:');
    envKeys.forEach(key => {
      const value = process.env[key];
      const displayValue = sanitizeForLog(key, value);
      console.log(`   ${key} = ${displayValue || '(not set)'}`);
    });
    console.log('');
  }

  return { missing, weak, valid: missing.length === 0 };
};

// Run validation on module load
const validation = validateSecrets();

// ========================================
// Configuration Export
// ========================================

const config = {
  // Environment info
  env: env,
  isProduction: env === 'production',
  isDevelopment: env === 'development',
  isTest: env === 'test',
  isStaging: env === 'staging',

  /**
   * Get a required secret - throws in production if missing
   * @param {string} key - Environment variable name
   * @returns {string}
   */
  requireSecret: (key) => {
    const value = process.env[key];
    if (!value) {
      if (env === 'production') {
        throw new Error(`Required secret "${key}" not found in environment`);
      }
      console.warn(`⚠️  Secret "${key}" not found, returning null`);
    }
    return value;
  },

  /**
   * Get an optional secret with safe fallback for non-production
   * @param {string} key - Environment variable name
   * @param {string} fallback - Fallback value (ONLY for dev/test)
   * @returns {string}
   */
  optionalSecret: (key, fallback) => {
    const value = process.env[key];
    if (value) return value;

    if (env === 'production') {
      throw new Error(`Secret "${key}" not found and no fallback allowed in production`);
    }
    console.warn(`⚠️  Using fallback for secret "${key}" in ${env} mode`);
    return fallback;
  },

  /**
   * Get a configuration value with validation
   * @param {string} key - Environment variable name
   * @param {*} defaultValue - Default value if not set
   * @returns {*}
   */
  get: (key, defaultValue) => {
    const value = process.env[key];
    return value !== undefined ? value : defaultValue;
  },

  /**
   * Type-safe getters
   */
  getString: (key, defaultValue = '') => config.get(key, defaultValue),
  getBoolean: (key, defaultValue = false) => getBoolean(key, defaultValue),
  getInt: (key, defaultValue = 0) => getInt(key, defaultValue),
  getArray: (key, defaultValue = []) => getArray(key) || defaultValue,
  getUrl: (key, defaultValue = null) => getUrl(key, defaultValue),

