#!/usr/bin/env node

/**
 * Secret Rotation Script
 * 
 * Usage:
 *   node scripts/rotate-secrets.js              # Rotate all secrets
 *   node scripts/rotate-secrets.js --list       # List all secrets
 *   node scripts/rotate-secrets.js --jwt        # Rotate only JWT_SECRET
 *   node scripts/rotate-secrets.js --dry-run    # Preview changes
 * 
 * SECURITY: This script generates new secrets and updates .env files.
 * Ensure .env files are properly secured (chmod 600) after running.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const args = process.argv.slice(2);

// ==========================================
// Secret Definitions
// ==========================================

const secretDefinitions = {
  JWT_SECRET: {
    description: 'JWT signing secret',
    generate: () => crypto.randomBytes(64).toString('hex'),
    minLength: 32,
    pattern: /^.{32,}$/
  },
  SESSION_SECRET: {
    description: 'Session encryption secret',
    generate: () => crypto.randomBytes(32).toString('base64'),
    minLength: 24,
    pattern: /^.{24,}$/
  },
  API_SECRET: {
    description: 'Internal API secret',
    generate: () => crypto.randomBytes(48).toString('hex'),
    minLength: 32,
    pattern: /^.{32,}$/
  }
};

// ==========================================
// Utilities
// ==========================================

const colors = {
  red: (text) => `\x1b[31m${text}\x1b[0m`,
  green: (text) => `\x1b[32m${text}\x1b[0m`,
  yellow: (text) => `\x1b[33m${text}\x1b[0m`,
  blue: (text) => `\x1b[34m${text}\x1b[0m`,
  gray: (text) => `\x1b[90m${text}\x1b[0m`
};

const log = {
  info: (msg) => console.log(`ℹ️  ${msg}`),
  success: (msg) => console.log(colors.green(`✅ ${msg}`)),
  warning: (msg) => console.log(colors.yellow(`⚠️  ${msg}`)),
  error: (msg) => console.log(colors.red(`❌ ${msg}`)),
  header: (msg) => console.log(colors.blue(`\n${msg}`))
};

// ==========================================
// Environment File Operations
// ==========================================

const findEnvFiles = () => {
  const files = [];
  const cwd = process.cwd();

  // Check for common .env files
  const envFileNames = [
    '.env.development',
    '.env.test',
    '.env.staging',
    '.env.production',
    '.env.local'
  ];

  for (const filename of envFileNames) {
    const filepath = path.join(cwd, filename);
    if (fs.existsSync(filepath)) {
      files.push({ name: filename, path: filepath });
    }
  }

  return files;
};

const parseEnvFile = (content) => {
  const env = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip comments and empty lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse key=value
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();

      // Remove quotes if present
      const unquoted = value.replace(/^["']|["']$/g, '');
      env[key] = unquoted;
    }
  }

  return env;
};

const updateEnvFile = (filepath, updates, dryRun = false) => {
  let content = fs.readFileSync(filepath, 'utf8');
  const env = parseEnvFile(content);

  let updated = [];

  for (const [key, newValue] of Object.entries(updates)) {
    let found = false;
    const oldValue = env[key];

    // Pattern to match KEY=value with comments
    const regex = new RegExp(`^(\\s*${key}\\s*=\\s*)(?:[^\\n\\r#]+)`);

    if (regex.test(content)) {
      // Replace existing value
      content = content.replace(regex, `$1${newValue}`);
      found = true;

      updated.push({
        key,
        old: oldValue ? `${oldValue.slice(0, 4)}...` : '(empty)',
        new: `${newValue.slice(0, 4)}...`
      });
    }

    if (!found && newValue !== null) {
      // Append new secret
      content += `\n${key}=${newValue}`;

      updated.push({
        key,
        old: '(new)',
        new: `${newValue.slice(0, 4)}...`
      });
    }
  }

  if (!dryRun) {
    // Ensure trailing newline
    if (!content.endsWith('\n')) {
      content += '\n';
    }

    fs.writeFileSync(filepath, content, 'utf8');
  }

  return updated;
};

// ==========================================
// Secret Management Operations
// ==========================================

const listSecrets = (envFiles) => {
  log.header('📋 Current Secrets Status');

  for (const envFile of envFiles) {
    log.info(`\n${colors.gray(envFile.name)}:`);

    const content = fs.readFileSync(envFile.path, 'utf8');
    const env = parseEnvFile(content);

    for (const [key, definition] of Object.entries(secretDefinitions)) {
      const value = env[key];

      if (value) {
        // Check strength
        const length = value.length;
        const minLength = definition.minLength;
        const isStrong = length >= minLength;

        const status = isStrong ? colors.green('✓') : colors.yellow('⚠');
        const display = isStrong 
          ? `${status} ${key} (${length} chars)`
          : `${status} ${key} (${length} chars - too short, min ${minLength})`;

        console.log(`  ${display}`);
      } else {
        console.log(`  ⤷ ${key} (not set)`);
      }
    }
  }
};

const rotateSecrets = (envFiles, dryRun = false) => {
  log.header(crypt(dryRun ? '🔍 DRY RUN - Preview Changes' : '🔄 Rotating Secrets'));

  // Determine which secrets to rotate
  let secretsToRotate = args.filter(arg => !arg.startsWith('--'));
  if (secretsToRotate.length === 0 || args.includes('--all')) {
    secretsToRotate = Object.keys(secretDefinitions);
  }

  for (const envFile of envFiles) {
    log.info(`\n${colors.gray(envFile.name)}:`);

    // Skip production in dry-run (too dangerous)
    if (envFile.name.includes('production') && !args.includes('--force')) {
      log.warning(`Skipping ${envFile.name} (use --force to update production)`);
      continue;
    }

    // Skip .env.test (use canary values)
    if (envFile.name.includes('test')) {
      log.info(`Skipping ${envFile.name} (use canary detection values)`);
      continue;
    }

    const updates = {};

    for (const secretKey of secretsToRotate) {
      const definition = secretDefinitions[secretKey];

      if (!definition) {
        log.warning(`  Unknown secret: ${secretKey}`);
        continue;
      }

      // Generate new secret
      const newValue = definition.generate();
      updates[secretKey] = newValue;

      log.info(`  + ${secretKey}: ${colors.gray('generating new value...')}`);
    }

    // Update file
    if (Object.keys(updates).length > 0) {
      const updated = updateEnvFile(envFile.path, updates, dryRun);

      for (const change of updated) {
        log.success(`  ✓ ${change.key}: ${change.old} → ${change.new}`);
      }

      if (!dryRun) {
        // Secure file permissions
        fs.chmodSync(envFile.path, 0o600);
        log.info(`  ✓ Secured file permissions (600)`);
      }
    }
  }

  if (dryRun) {
    log.warning('\nThis was a dry run. Run without --dry-run to apply changes.');
  } else {
    log.success('\n✨ Secrets rotated successfully!');
    log.warning('📝 Don\'t forget to:');
    log.warning('   1. Update any systems using the old secrets');
    log.warning('   2. Invalidate any JWT tokens signed with old JWT_SECRET');
    log.warning('   3. Restart application servers');
  }
};

const validateSecrets = (envFiles) => {
  log.header('🔍 Validating Secrets');

  let hasIssues = false;

  for (const envFile of envFiles) {
    log.info(`\n${colors.gray(envFile.name)}:`);

    const content = fs.readFileSync(envFile.path, 'utf8');
    const env = parseEnvFile(content);

    for (const [key, definition] of Object.entries(secretDefinitions)) {
      const value = env[key];

      if (!value) {
        log.error(`  ✗ ${key} - not set`);
        hasIssues = true;
        continue;
      }

      // Validate length
      if (value.length < definition.minLength) {
        log.error(`  ✗ ${key} - too short (${value.length} < ${definition.minLength})`);
        hasIssues = true;
        continue;
      }

      // Validate pattern
      if (!definition.pattern.test(value)) {
        log.warning(`  ⚠ ${key} - doesn't match expected pattern`);
        hasIssues = true;
        continue;
      }

      log.success(`  ✓ ${key} (${value.length} chars)`);
    }
  }

  console.log('');

  if (hasIssues) {
    log.error('Validation failed - some secrets need attention');
    process.exit(1);
  } else {
    log.success('All secrets are valid!');
  }
};

// ==========================================
// Main
// ==========================================

const main = () => {
  log.header('🔐 Secret Management Tool');

  // Find .env files
  const envFiles = findEnvFiles();

  if (envFiles.length === 0) {
    log.error('No .env files found in current directory');
    log.info('Create one using: cp .env.example .env.development');
    process.exit(1);
  }

  log.info(`Found ${envFiles.length} environment file(s):`);
  envFiles.forEach(f => log.info(`  - ${f.name}`));

  // Parse commands
  const dryRun = args.includes('--dry-run');

  if (args.includes('--list') || args.includes('-l')) {
    listSecrets(envFiles);
  } else if (args.includes('--validate') || args.includes('-v')) {
    validateSecrets(envFiles);
  } else {
    rotateSecrets(envFiles, dryRun);
  }
};

// Run
main();

