### Using AWS Systems Manager (SSM) Parameter Store

```javascript
// config/ssm.js
const SSM = require('aws-sdk/clients/ssm');
const { promisify } = require('util');

const ssm = new SSM({ region: process.env.AWS_REGION || 'us-east-1' });

const getParameter = async (name, withDecryption = true) => {
  const result = await ssm.getParameter({
    Name: `/app/${process.env.NODE_ENV}/${name}`,
    WithDecryption: withDecryption
  }).promise();

  return result.Parameter.Value;
};

// Load all secrets from SSM
const loadFromSSM = async () => {
  const secrets = {
    JWT_SECRET: await getParameter('jwt-secret'),
    SESSION_SECRET: await getParameter('session-secret'),
    DATABASE_URL: await getParameter('database-url'),
    // ... more secrets
  };

  // Set as environment variables
  Object.assign(process.env, secrets);
  return secrets;
};

module.exports = { loadFromSSM, getParameter };
```

