 * - WEBHOOK_URL: https://localhost:3003/api/rotation-log
 * - WEBHOOK_API_KEY: Your authentication token
 * - WEBHOOK_SECRET: For HMAC signature
 * - SECURITY_TEAM_PUBLIC_KEY: For payload encryption (optional but recommended)
 */

const https = require('https');
const crypto = require('crypto');
const fs = require('fs');

/**
 * Validates the webhook URL meets security requirements
 */
function validateWebhookUrl(url) {
  const errors = [];

  if (!url.startsWith('https://')) {
    errors.push('Webhook URL must use HTTPS (not HTTP)');
  }

  const parsed = new URL(url);
  if (parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1') {
    console.warn('⚠️  Warning: localhost endpoint - ensure network isolation');
  }

  return errors;
}

/**
 * Creates HMAC signature for payload integrity
 */
function signPayload(payload, secret) {
  if (!secret) {
    throw new Error('WEBHOOK_SECRET environment variable is required');
  }

  return crypto
    .createHmac('sha256', secret)
    .update(JSON.stringify(payload))
    .digest('hex');
}

/**
 * Encrypts payload using RSA public key (optional but recommended)
 */
function encryptPayload(content, publicKeyPem) {
  if (!publicKeyPem) {
    return { encrypted: false, data: content };
  }

  const buffer = Buffer.from(content, 'utf8');
  const encrypted = crypto.publicEncrypt({
    key: publicKeyPem,
    padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
    oaepHash: 'sha256',
  }, buffer);

  return { encrypted: true, data: encrypted.toString('base64') };
}

/**
 * Sends rotation log to secure webhook endpoint
 */
async function sendRotationLog(logFilePath, options = {}) {
  // Validate environment
  const webhookUrl = process.env.WEBHOOK_URL;
  const apiKey = process.env.WEBHOOK_API_KEY;
  const secret = process.env.WEBHOOK_SECRET;

  if (!webhookUrl || !apiKey || !secret) {
    throw new Error(
      'Missing required environment variables: WEBHOOK_URL, WEBHOOK_API_KEY, WEBHOOK_SECRET'
    );
  }

  // Validate URL security
  const urlErrors = validateWebhookUrl(webhookUrl);
  if (urlErrors.length > 0) {
    throw new Error(`Invalid webhook URL:\n${urlErrors.join('\n')}`);
  }

  // Read the rotation log
  if (!fs.existsSync(logFilePath)) {
    throw new Error(`Rotation log not found: ${logFilePath}`);
  }

  const logContent = fs.readFileSync(logFilePath, 'utf8');

  console.log('📋 Rotation Log Summary:');
  console.log(`   File: ${logFilePath}`);
  console.log(`   Size: ${logContent.length} bytes`);
  console.log(`   Lines: ${logContent.split('\n').length}`);

  // Prepare payload
  const payload = {
    credentials: logContent,
    metadata: {
      filename: path.basename(logFilePath),
      size: logContent.length,
      sent_at: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
      source: process.env.HOSTNAME || 'unknown',
    },
  };

  // Sign payload
  const signature = signPayload(payload, secret);

  // Encrypt if public key available
  const encryption = encryptPayload(
    logContent,
    process.env.SECURITY_TEAM_PUBLIC_KEY
  );

  if (encryption.encrypted) {
    payload.credentials = encryption.data;
    payload.encryption = {
      method: 'RSA-OAEP-SHA256',
      version: '1.0',
    };
  }

  // Prepare request
  const url = new URL(webhookUrl);
  const postData = JSON.stringify(payload);

  const requestOptions = {
    hostname: url.hostname,
    port: url.port || 443,
    path: url.pathname + url.search,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData),
      'Authorization': `Bearer ${apiKey}`,
      'X-Signature': signature,
      'X-Timestamp': Date.now().toString(),
      'X-Environment': process.env.NODE_ENV || 'development',
    },
    // CRITICAL: Reject invalid certificates
    rejectUnauthorized: true,
  };

  console.log('\n🔒 Sending secure webhook request...');
  console.log(`   URL: ${webhookUrl}`);
  console.log(`   Encrypted: ${encryption.encrypted ? 'Yes' : 'No'}`);
  console.log(`   Signature: ${signature.substring(0, 16)}...`);

  // Send request
  return new Promise((resolve, reject) => {
    const req = https.request(requestOptions, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const response = JSON.parse(responseData);

          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`\n✅ Success! Server responded: ${res.statusCode}`);
            console.log(`   Response: ${JSON.stringify(response, null, 2)}`);
            resolve({ status: res.statusCode, response });
          } else {
            console.error(`\n❌ Error! Server responded: ${res.statusCode}`);
            console.error(`   Response: ${responseData}`);
            reject(new Error(`Webhook returned ${res.statusCode}`));
          }
        } catch (error) {
          reject(new Error(`Failed to parse response: ${error.message}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('\n❌ Request failed:', error.message);
      reject(error);
    });

    // Timeout after 30 seconds
    req.setTimeout(30000, () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });

    req.write(postData);
    req.end();
  });
}

// Main execution
if (require.main === module) {
  const logFile = process.argv[2] || './rotation-log.md';

  console.log('🔐 Secure Webhook Client for Rotation Logs\n');

  sendRotationLog(logFile)
    .then(() => {
      console.log('\n✨ Rotation log sent successfully');
      process.exit(0);
    })
    .catch((error) => {
      console.error('\n💥 Failed to send rotation log:', error.message);
      process.exit(1);
    });
}

module.exports = { sendRotationLog, validateWebhookUrl };

