 * - Caching with TTL
 * - Automatic rotation support
 * - Fallback for local development
 */

const AWS = require('aws-sdk');
const NodeCache = require('node-cache');

// Cache secrets to reduce API calls (5 minute TTL)
const secretsCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

// Initialize Secrets Manager client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
  // Use IAM role credentials, not access keys
  // Do NOT hardcode AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY
});

/**
 * Fetch secret from AWS Secrets Manager with caching
 * @param {string} secretName - Name/ARN of the secret
 * @returns {Promise<string>} - Secret value
 */
async function getSecret(secretName) {
  // Check cache first
  const cachedSecret = secretsCache.get(secretName);
  if (cachedSecret) {
    return cachedSecret;
  }

  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    let secret;
    if ('SecretString' in data) {
      secret = data.SecretString;
    } else {
      // Binary secret
      secret = Buffer.from(data.SecretBinary, 'base64').toString('utf-8');
    }

    // Parse JSON secrets
    try {
      const parsed = JSON.parse(secret);
      secretsCache.set(secretName, parsed);
      return parsed;
    } catch {
      secretsCache.set(secretName, secret);
      return secret;
    }
  } catch (error) {
    console.error(`Error fetching secret ${secretName}:`, error.message);

    // Fallback to environment variables in development only
    if (process.env.NODE_ENV !== 'production') {
      console.warn(`Falling back to environment variable for ${secretName}`);
      return process.env[secretName];
    }

    throw new Error(`Failed to retrieve secret: ${secretName}`);
  }
}

/**
 * Get all application secrets
 * @returns {Promise<Object>} - Object containing all secrets
 */
async function getAllSecrets() {
  const secrets = await getSecret('prod/application/secrets');
  return secrets;
}

/**
 * Force clear cache (useful for testing or after rotation)
 */
function clearCache() {
  secretsCache.flushAll();
}

/**
 * health check for secrets manager
 */
async function healthCheck() {
  try {
    await secretsManager.describeSecret({ SecretId: 'prod/application/secrets' }).promise();
    return { status: 'healthy' };
  } catch (error) {
    return { status: 'unhealthy', error: error.message };
  }
}

