### Option 1: AWS Secrets Manager (Recommended for AWS deployments)

```javascript
// Load secrets securely from AWS Secrets Manager
const AWS = require('aws-sdk');
const { SMClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    // Use IAM role-based authentication, not access keys
    this.client = new SMClient({ 
      region: process.env.AWS_REGION || 'us-west-2' 
    });
    this.cache = new Map();
    this.cacheTimeout = 300000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT' // Always get the current version
      });

      const response = await this.client.send(command);
      const secretString = response.SecretString;
      const secret = JSON.parse(secretString);

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseUrl() {
    const secret = await this.getSecret('production/database');
    return secret.connection_string;
  }

  async getStripeKey() {
    const secret = await this.getSecret('production/stripe');
    return secret.secret_key;
  }

  async getAnthropicApiKey() {
    const secret = await this.getSecret('production/anthropic');
    return secret.api_key;
  }

  async getAWSCredentials() {
    // For cross-service AWS access, use IAM roles, not stored keys
    // This is just for reference - typically not needed in Lambda/ECS
    const secret = await this.getSecret('production/aws-credentials');
    return {
      accessKeyId: secret.aws_access_key_id,
      secretAccessKey: secret.aws_secret_access_key
    };
  }

  // Clear cache (useful after rotation)
  clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = SecretsManager;
```

