### **Option 1: AWS Secrets Manager (Recommended for Production)**

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Load secrets from AWS Secrets Manager
async function loadSecrets() {
  const client = new SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    const response = await client.send(new GetSecretValueCommand({
      SecretId: process.env.SECRET_ARN || 'prod/app/secrets'
    }));

    if (response.SecretString) {
      const secrets = JSON.parse(response.SecretString);

      // Set environment variables
      process.env.DATABASE_URL = secrets.DATABASE_URL;
      process.env.AWS_ACCESS_KEY_ID = secrets.AWS_ACCESS_KEY_ID;
      process.env.AWS_SECRET_ACCESS_KEY = secrets.AWS_SECRET_ACCESS_KEY;
      process.env.ANTHROPIC_API_KEY = secrets.ANTHROPIC_API_KEY;
      process.env.STRIPE_SECRET_KEY = secrets.STRIPE_SECRET_KEY;
      process.env.JWT_SECRET = secrets.JWT_SECRET;

      return secrets;
    }
  } catch (error) {
    console.error('Error loading secrets:', error);
    throw error;
  }
}

// Initialize app with secrets
async function initializeApp() {
  await loadSecrets();

  const express = require('express');
  const app = express();

  // ... rest of your app

  return app;
}

module.exports = initializeApp();
