```javascript
// config/secrets.js - Unified secrets management
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    // Use environment variables to bootstrap only the secret manager access
    this.region = process.env.AWS_REGION || 'us-east-1';
    this.cache = {};
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache[secretName];
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    // Fetch from Secrets Manager
    const client = new SecretsManagerClient({ region: this.region });

    try {
      const response = await client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : response.SecretBinary;

      // Cache the result
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed for ${secretName}`);
    }
  }

  // Get a specific secret value
  async getDatabaseUrl() {
    const secret = await this.getSecret(process.env.DB_SECRET_NAME || 'prod/database');
    return secret.connection_string || secret.url;
  }

  async getStripeKey() {
    const secret = await this.getSecret(process.env.STRIPE_SECRET_NAME || 'prod/stripe');
    return secret.secret_key;
  }

  async getAnthropicApiKey() {
    const secret = await this.getSecret(process.env.ANTHROPIC_SECRET_NAME || 'prod/anthropic');
    return secret.api_key;
  }

  async getAwsCredentials() {
    // For AWS credentials, prefer IAM roles when running on EC2/ECS/Lambda
    if (process.env.AWS_CONTAINER_CREDENTIALS_RELATIVE_URI || 
        process.env.AWS_EC2_METADATA_SERVICE_ENDPOINT) {
      return { useIamRole: true };
    }

    const secret = await this.getSecret(process.env.AWS_CREDENTIALS_SECRET_NAME || 'prod/aws-credentials');
    return {
      accessKeyId: secret.access_key_id,
      secretAccessKey: secret.secret_access_key
    };
  }
}

module.exports = new SecretsManager();
```

