      // Load environment-specific .env first
      if (fs.existsSync(envFile)) {
        this.checkFilePermissions(envFile);
        const result = dotenv.config({ path: envFile });
        if (result.error) throw result.error;
      }

      // Load default .env as fallback
      if (fs.existsSync(defaultEnvFile) && !fs.existsSync(envFile)) {
        this.checkFilePermissions(defaultEnvFile);
        dotenv.config({ path: defaultEnvFile });
      }
    }

    this.config = process.env;
  }

  checkFilePermissions(filePath) {
    // Security: Ensure .env files have restrictive permissions
    const stats = fs.statSync(filePath);
    const mode = stats.mode & 0o777;

    if (mode !== 0o600 && mode !== 0o400) {
      console.warn(`⚠️  Warning: ${filePath} has insecure permissions (${mode.toString(8)}). Should be 600.`);
    }
  }

  validate() {
    const missing = [];
    const suspicious = [];

    for (const varName of REQUIRED_VARS) {
      if (!this.config[varName]) {
        missing.push(varName);
      }
    }

    for (const [key, value] of Object.entries(this.config)) {
      for (const forbidden of FORBIDDEN_DEFAULT_VALUES) {
        if (value && value.toLowerCase().includes(forbidden.toLowerCase())) {
          suspicious.push({ key, value, contains: forbidden });
        }
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }

    if (suspicious.length > 0) {
      const errors = suspicious.map(s => 
        `${s.key} contains forbidden value "${s.contains}"`
      );
      throw new Error(`Suspicious environment variable values detected:\n  - ${errors.join('\n  - ')}`);
    }

    // Security: Warn if running in development with production-like data
    if (this.config.NODE_ENV === 'development' && 
        this.config.DATABASE_URL?.includes('production')) {
      console.warn('⚠️  Warning: Using production database in development mode!');
    }
  }

  get(key, defaultValue = undefined) {
    return this.config[key] || defaultValue;
  }

  getRequired(key) {
    const value = this.get(key);
    if (value === undefined) {
      throw new Error(`Required environment variable ${key} is not set`);
    }
    return value;
  }

  // Secure logging - masks sensitive values
  logConfigSafe() {
    const sensitiveKeys = [
      'SECRET', 'KEY', 'PASSWORD', 'TOKEN', 
      'DATABASE_URL', 'CONNECTION_STRING'
    ];

    const safeConfig = {};
    for (const [key, value] of Object.entries(this.config)) {
      const isSensitive = sensitiveKeys.some(sensitive => 
        key.toUpperCase().includes(sensitive)
      );
      safeConfig[key] = isSensitive ? '***REDACTED***' : value;
    }

    return safeConfig;
  }
}

// Singleton instance
const envConfig = new SecureEnvConfig();

module.exports = envConfig;
```

