  if [ "$PERMS" != "600" ]; then
    echo "⚠️  Warning: .env has insecure permissions ($PERMS). Setting to 600..."
    chmod 600 .env
  fi
fi

# In production, ensure NO .env files exist (use env vars or Secrets Manager)
if [ "${NODE_ENV:-}" = "production" ] && [ -f .env ]; then
  echo "❌ ERROR: .env file exists in production environment!"
  echo "   Use environment variables or AWS Secrets Manager instead."
  exit 1
fi

# Check for secrets in git history (only in development)
if [ "${NODE_ENV:-}" != "production" ]; then
  if git log --all --full-history --source --pretty=format:"%H" -- "*.env" | grep -q .; then
    echo "⚠️  Warning: .env files found in git history!"
    echo "   Consider: git filter-branch --force --index-filter 'git rm --cached .env' --prune-empty --tag-name-filter cat -- --all"
  fi
fi

echo "✅ Secrets validation passed"
echo "🚀 Starting deployment..."

