```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsLoader {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async loadSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if (response.SecretString) {
        const secretValue = JSON.parse(response.SecretString);

        // Cache the result
        this.cache.set(secretName, {
          value: secretValue,
          timestamp: Date.now()
        });

        return secretValue;
      }
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  // Load all secrets at startup
  async loadAllSecrets() {
    try {
      const dbCredentials = await this.loadSecret('prod/database/credentials');
      const apiKeys = await this.loadSecret('prod/api/keys');
      const jwtConfig = await this.loadSecret('prod/auth/jwt');

      return {
        database: dbCredentials,
        api: apiKeys,
        auth: jwtConfig
      };
    } catch (error) {
      console.error('Failed to load secrets:', error);
      throw error;
    }
  }
}

module.exports = new SecretsLoader();
```

