/**
 * Centralized Secrets Management Module
 * 
 * This module provides a secure way to load and access secrets from multiple sources:
 * 1. Environment variables (from .env files, process.env, or container orchestration)
 * 2. AWS Secrets Manager (production)
 * 3. Fallback to local .env files (development/staging)
 * 
 * SECURITY PRINCIPLES:
 * - Never log actual secret values
 * - Validate required secrets at startup
 * - Provide clear error messages for missing secrets
 * - Support secrets rotation without restart
 */

const dotenv = require('dotenv');
const path = require('path');

/**
 * Load environment variables from .env files
 * Priority: .env.{NODE_ENV} -> .env -> process.env
 */
function loadEnvironment() {
  const env = process.env.NODE_ENV || 'development';

  // Load environment-specific .env file (highest priority)
  const envPath = path.resolve(process.cwd(), `.env.${env}`);
  dotenv.config({ path: envPath });

  // Load default .env file (fallback)
  const defaultPath = path.resolve(process.cwd(), '.env');
  if (env !== 'development') {
    dotenv.config({ path: defaultPath });
  }

  return env;
}

/**
 * Required secrets configuration
 */
const REQUIRED_SECRETS = {
  production: [
    'SESSION_SECRET',
    'JWT_SECRET',
    'API_TOKEN',
    'DATABASE_URL'
  ],
  staging: [
    'SESSION_SECRET',
    'JWT_SECRET'
  ],
  development: []
};

const OPTIONAL_SECRETS = [
  'REDIS_URL',
  'ALLOWED_ORIGINS',
  'COOKIES_DOMAIN',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

/**
 * Secrets Manager Class
 */
class SecretsManager {
  constructor(env = 'development') {
    this.env = env;
    this.secrets = {};
    this.isLoaded = false;
  }

  /**
   * Load all secrets
   */
  async load() {
    // 1. Load from environment variables (container/platform injected)
    this._loadFromEnvironment();

    // 2. For production, optionally load from AWS Secrets Manager
    if (this.env === 'production') {
      await this._loadFromAWS();
    }

    // 3. Validate required secrets are present
    this._validateSecrets();

    this.isLoaded = true;

    // Log that secrets are loaded (never log actual values)
    console.log(`[Secrets] Loaded ${Object.keys(this.secrets).length} secrets for environment: ${this.env}`);

    return this.secrets;
  }

  /**
   * Load secrets from environment variables
   * @private
   */
  _loadFromEnvironment() {
    const allSecretNames = [...REQUIRED_SECRETS[this.env] || [], ...OPTIONAL_SECRETS];

    for (const name of allSecretNames) {
      const value = process.env[name];
      if (value !== undefined) {
        this.secrets[name] = value;
      }
    }
  }

  /**
   * Load secrets from AWS Secrets Manager (production only)
   * @private
   */
  async _loadFromAWS() {
    try {
      // Only require AWS SDK if needed
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

      const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

      // List of secrets to fetch from AWS
      const secretNames = [
        `/app/${this.env}/database`,
        `/app/${this.env}/jwt`,
        `/app/${this.env}/session`,
        `/app/${this.env}/payment`
      ];

      for (const secretName of secretNames) {
        try {
          const command = new GetSecretValueCommand({ SecretId: secretName });
          const response = await client.send(command);

          if (response.SecretString) {
            const secret = JSON.parse(response.SecretString);
            // Merge loaded secret with our secrets object
            Object.assign(this.secrets, secret);
          }
        } catch (err) {
          // Secret might not exist, that's okay for optional secrets
          if (err.name !== 'ResourceNotFoundException') {
            console.warn(`[Secrets] Could not load AWS secret: ${secretName}`, err.message);
          }
        }
      }
    } catch (err) {
      // AWS SDK not installed or not configured
      console.warn('[Secrets] AWS Secrets Manager not available, using environment variables');
    }
  }

  /**
   * Validate that all required secrets are present
   * @private
   */
  _validateSecrets() {
    const required = REQUIRED_SECRETS[this.env] || [];
    const missing = required.filter(name => !this.secrets[name]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets for ${this.env}: ${missing.join(', ')}\n` +
        `Please set these environment variables or add them to .env.${this.env}`
      );
    }

    // Validate secret strength
    this._validateSecretStrength();
  }

  /**
   * Ensure secrets meet minimum security requirements
   * @private
   */
  _validateSecretStrength() {
    const checks = {
      SESSION_SECRET: { minLength: 32 },
      JWT_SECRET: { minLength: 32 },
      API_TOKEN: { minLength: 16 }
    };

    const warnings = [];

    for (const [secretName, requirement] of Object.entries(checks)) {
      const value = this.secrets[secretName];
      if (value && value.length < requirement.minLength) {
        warnings.push(
          `${secretName} is too short (${value.length} chars, minimum ${requirement.minLength})`
        );
      }
    }

    if (warnings.length > 0) {
      console.warn('[Secrets] Weak secrets detected:');
      warnings.forEach(w => console.warn(`  ⚠️  ${w}`));
      console.warn('[Secrets] Consider generating stronger secrets using: openssl rand -base64 64');
    }
  }

  /**
   * Get a secret value
   * @param {string} name - Secret name
   * @param {any} defaultValue - Default value if secret not found
   * @returns {any} Secret value or default
   */
  get(name, defaultValue = undefined) {
    return this.secrets[name] !== undefined ? this.secrets[name] : defaultValue;
  }

  /**
   * Check if a secret exists
   * @param {string} name - Secret name
   * @returns {boolean}
   */
  has(name) {
    return this.secrets[name] !== undefined;
  }

  /**
   * Get all secrets (use with caution - never log this!)
   * @returns {object} All secrets
   */
  getAll() {
    return { ...this.secrets };
  }

  /**
   * Reload secrets from their sources
   */
  async reload() {
    console.log('[Secrets] Reloading secrets...');
    this.secrets = {};
    await this.load();
  }
}

/**
 * Singleton instance
 */
let secretsManagerInstance = null;

/**
 * Get or create the Secrets Manager singleton
 * @param {string} env - Environment name
 * @returns {SecretsManager}
 */
function getSecretsManager(env = process.env.NODE_ENV) {
  if (!secretsManagerInstance) {
    secretsManagerInstance = new SecretsManager(env);
  }
  return secretsManagerInstance;
}

/**
 * Initialize and load all secrets
 * @param {string} env - Environment name
 * @returns {Promise<SecretsManager>}
 */
async function initSecrets(env) {
  loadEnvironment();
  const manager = getSecretsManager(env);
  await manager.load();
  return manager;
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  initSecrets,
  loadEnvironment
};

/**
 * Secure Express Application with Proper Secrets Management
 * 
 * This version properly loads secrets from environment variables and validates them at startup.
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const slowDown = require('express-slow-down');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');
const compression = require('compression');
const timeout = require('connect-timeout');
const hpp = require('hpp');
const { initSecrets } = require('./secrets-manager');

// ============================================================================
// INITIALIZE SECRETS - MUST BE FIRST
// ============================================================================

async function startServer() {
  try {
    // Load and validate all secrets before starting server
    console.log('[Startup] Loading secrets...');
    const secrets = await initSecrets(process.env.NODE_ENV || 'development');

    const app = express();

    // ============================================================================
    // CONFIGURATION (from secrets/environment)
    // ============================================================================

    const config = {
      // Server configuration
      port: secrets.get('PORT', 3000),
      host: secrets.get('HOST', '0.0.0.0'),
      env: secrets.get('NODE_ENV', 'development'),

      // Security configuration
      sessionSecret: secrets.get('SESSION_SECRET'),
      jwtSecret: secrets.get('JWT_SECRET'),
      apiToken: secrets.get('API_TOKEN'),

      // CORS configuration
      allowedOrigins: secrets.get('ALLOWED_ORIGINS', 'http://localhost:3000').split(','),

      // Database configuration
      databaseUrl: secrets.get('DATABASE_URL'),

      // Optional services
      redisUrl: secrets.get('REDIS_URL'),
      awsRegion: secrets.get('AWS_REGION', 'us-east-1'),

      // Secret existence status (for conditional features)
      hasRedis: secrets.has('REDIS_URL'),
      hasDatabase: secrets.has('DATABASE_URL')
    };

    // ============================================================================
    // SECURITY MIDDLEWARE
    // ============================================================================

    // Disable Express version disclosure
    app.disable('x-powered-by');

    // Security headers with Helmet
    app.use(helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          imgSrc: ["'self'", "data:", "https:"],
        },
      },
      hsts: config.env === 'production' ? {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
      } : false,
      noSniff: true,
      frameguard: { action: 'deny' },
      xssFilter: true
    }));

    // CORS configuration
    app.use(cors({
      origin: config.allowedOrigins,
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE'],
      allowedHeaders: ['Content-Type', 'Authorization']
    }));

    // Request size limits to prevent DoS
    app.use(express.json({ limit: '10kb' }));
    app.use(express.urlencoded({ limit: '10kb', extended: true }));

    // Compression
    app.use(compression({
      filter: (req, res) => {
        if (req.headers['x-no-compression']) {
          return false;
        }
        return compression.filter(req, res);
      }
    }));

    // Request timeout
    app.use(timeout('30s'));

    // Prevent HTTP parameter pollution
    app.use(hpp());

    // ============================================================================
    // RATE LIMITING
    // ============================================================================

    // General API rate limiter
    const apiLimiter = rateLimit({
      windowMs: 15 * 60 * 1000,
      max: 100,
      message: {
        error: 'Too many requests from this IP, please try again after 15 minutes'
      },
      standardHeaders: true,
      legacyHeaders: false,
      skip: (req) => req.ip === '127.0.0.1' || req.ip === '::1'
    });

    // Slow down requests approaching the limit
    const speedLimiter = slowDown({
      windowMs: 15 * 60 * 1000,
      delayAfter: 50,
      delayMs: 500,
      skip: (req) => req.ip === '127.0.0.1' || req.ip === '::1'
    });

    // Apply rate limiters
    app.use('/api/', apiLimiter);
    app.use('/api/', speedLimiter);

    // ============================================================================
    // LOGGING
    // ============================================================================

    // Configure Winston logger
    const logger = winston.createLogger({
      level: 'info',
      format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
      ),
      transports: [
        new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
        new winston.transports.File({ filename: 'logs/combined.log' })
      ]
    });

    if (config.env !== 'production') {
      logger.add(new winston.transports.Console({
        format: winston.format.simple()
      }));
    }

    // HTTP request logging with Morgan
    morgan.token('request-id', (req) => req.id);
    app.use(morgan(':method :url :status :res[content-length] - :response-time ms', {
      stream: {
        write: (message) => logger.info(message.trim())
      }
    }));

    // Request ID middleware
    app.use((req, res, next) => {
      req.id = req.headers['x-request-id'] || require('crypto').randomBytes(16).toString('hex');
      res.setHeader('X-Request-ID', req.id);
      next();
    });

    // Security event logging helper
    const logSecurityEvent = (event, details) => {
      // Never log actual secret values!
      logger.warn('Security Event', {
        event,
        ...details,
        timestamp: new Date().toISOString()
      });
    };

    // ============================================================================
    // VALIDATION MIDDLEWARE
    // ============================================================================

    const handleValidationErrors = (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logSecurityEvent('VALIDATION_ERROR', {
          ip: req.ip,
          path: req.path,
          errors: errors.array()
        });
        return res.status(400).json({ errors: errors.array() });
      }
      next();
    };

    // ============================================================================
    // AUTHENTICATION MIDDLEWARE
    // ============================================================================

    const authenticateUser = (req, res, next) => {
      const authHeader = req.headers.authorization;

      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        logSecurityEvent('UNAUTHORIZED_ACCESS_ATTEMPT', {
          ip: req.ip,
          path: req.path,
          userAgent: req.get('user-agent')
        });
        return res.status(401).json({ error: 'Unauthorized' });
      }

      const token = authHeader.slice(7);

      // Use the properly loaded API_TOKEN from secrets
      if (config.env === 'production' && config.apiToken && token !== config.apiToken) {
        logSecurityEvent('INVALID_TOKEN_ATTEMPT', {
          ip: req.ip,
          path: req.path
        });
        return res.status(401).json({ error: 'Invalid token' });
      }

      req.user = { id: 1, authenticated: true };
      next();
    };

    // ============================================================================
    // ROUTES
    // ============================================================================

    // Simple health check for load balancers (no auth)
    app.get('/healthz', (req, res) => {
      res.status(200).send('OK');
    });

    // Detailed health check (authenticated in production)
    app.get('/health', async (req, res) => {
      try {
        const health = {
          status: 'ok',
          environment: config.env,
          checks: {
            secrets: secrets.has('SESSION_SECRET') ? 'configured' : 'not configured',
            database: config.hasDatabase ? 'configured' : 'not configured',
            redis: config.hasRedis ? 'configured' : 'not configured'
          },
          timestamp: new Date().toISOString()
        };
        res.json(health);
      } catch (err) {
        logger.error('Health check failed', { error: err.message });
        res.status(503).json({ status: 'error' });
      }
    });

    // Config endpoint (development only, never in production!)
    if (config.env === 'development') {
      app.get('/config', (req, res) => {
        // Only show non-secret configuration
        res.json({
          port: config.port,
          host: config.host,
          environment: config.env,
          allowedOrigins: config.allowedOrigins,
          hasSecrets: {
            sessionSecret: !!config.sessionSecret,
            jwtSecret: !!config.jwtSecret,
            apiToken: !!config.apiToken,
            databaseUrl: !!config.databaseUrl
          }
        });
      });
    }

    // Protected users endpoint
    app.get('/users',
      authenticateUser,
      query('page').optional().isInt({ min: 1 }).toInt(),
      query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
      query('search').optional().trim().escape().isLength({ max: 100 }),
      handleValidationErrors,
      (req, res) => {
        const users = [
          { id: 1, name: 'Alice', email: 'alice@example.com' },
          { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];
        logger.info('Users accessed', { userId: req.user.id });
        res.json(users);
      }
    );

    // ============================================================================
    // ERROR HANDLING
    // ============================================================================

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({
        error: 'Not Found',
        path: req.path
      });
    });

    // Global error handler (must be last)
    app.use((err, req, res, next) => {
