}

// Generate JWT token
function generateToken(user, expiresIn = '1h') {
  const payload = {
    userId: user.id,
    role: user.role,
    iat: Math.floor(Date.now() / 1000),
  };

  return jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn,
    algorithm: 'HS256',
    issuer: process.env.APP_NAME,
    audience: process.env.APP_NAME,
  });
}

// Verify JWT token
function verifyToken(token) {
