      issuer: process.env.APP_NAME,
      audience: process.env.APP_NAME,
    });
  } catch (error) {
    return null;
  }
}

// Generate secure random token
function generateSecureToken(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

module.exports = {
  validatePassword,
  hashPassword,
  verifyPassword,
  generateToken,
  verifyToken,
  generateSecureToken,
  PASSWORD_REQUIREMENTS,
};
