```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { NodeHttpHandler } = require('@aws-sdk/node-http-handler');

class SecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION;
    this.cache = new Map();
    this.ttl = options.ttl || 300000; // 5 minutes default
    this.client = new AWS.SecretsManager({
      region: this.region,
      httpOptions: {
        timeout: options.timeout || 5000,
      },
    });
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.ttl) {
        return cached.value;
      }
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName,
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Secret retrieval failed');
    }
  }

  // Clear cache (useful for secret rotation)
  invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

module.exports = SecretsManager;
```

