// config/vault.js
const axios = require('axios');
const crypto = require('crypto');

class VaultSecrets {
  constructor(options = {}) {
    this.address = options.address || process.env.VAULT_ADDR;
    this.token = options.token || process.env.VAULT_TOKEN;
    this.mount = options.mount || 'secret';
    this.cache = new Map();
    this.client = axios.create({
      baseURL: this.address,
      headers: {
        'X-Vault-Token': this.token,
      },
      timeout: options.timeout || 5000,
    });
  }

  async getSecret(path) {
    // Check cache
    if (this.cache.has(path)) {
      const cached = this.cache.get(path);
      if (!this.isCacheExpired(cached)) {
        console.log(`Cache hit for: ${path}`);
        return cached.data;
      }
    }

    try {
      const response = await this.client.get(`/v1/${this.mount}/data/${path}`);
      const secret = response.data.data.data;

      // Cache with metadata
      this.cache.set(path, {
        data: secret,
        expiresAt: Date.now() + 300000, // 5 minutes
        hash: crypto.createHash('sha256').update(JSON.stringify(secret)).digest('hex'),
      });

      return secret;
    } catch (error) {
      console.error(`Vault error for ${path}:`, error.message);
      throw new Error('Secret retrieval from Vault failed');
    }
  }

  isCacheExpired(cached) {
    return Date.now() > cached.expiresAt;
  }

  // Rotate a secret
  async rotateSecret(path, newData) {
    try {
      await this.client.post(`/v1/${this.mount}/data/${path}`, {
        data: newData,
      });

      this.cache.delete(path);
      console.log(`Secret rotated: ${path}`);
    } catch (error) {
      console.error(`Rotation failed for ${path}:`, error.message);
      throw error;
    }
  }
}

module.exports = VaultSecrets;
