// config/env.js - For development only!
const crypto = require('crypto');
const fs = require('fs');

class SecureEnvLoader {
  constructor() {
    this.secrets = new Map();
    this.decryptionKey = this.getOrCreateKey();
  }

  // Generate or retrieve encryption key from secure storage
  getOrCreateKey() {
    // In production, this would use KMS or hardware security module
    const keyPath = process.env.ENCRYPTION_KEY_PATH || '/tmp/.env.key';

    try {
      if (fs.existsSync(keyPath)) {
        return fs.readFileSync(keyPath, 'utf8');
      }

      const key = crypto.randomBytes(32).toString('hex');
      fs.writeFileSync(keyPath, key, { mode: 0o600 });
      return key;
    } catch (error) {
      console.error('Failed to load encryption key');
      throw error;
    }
  }

  // Decrypt environment variable values
  decrypt(encryptedValue) {
    try {
      const [iv, authTag, encrypted] = encryptedValue.split(':');
      const decipher = crypto.createDecipheriv('aes-256-gcm', 
        Buffer.from(this.decryptionKey, 'hex'), 
        Buffer.from(iv, 'hex')
      );
      decipher.setAuthTag(Buffer.from(authTag, 'hex'));

      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return decrypted;
    } catch (error) {
      console.error('Decryption failed');
      throw error;
    }
  }

  // Load and decrypt secrets
  async load() {
    const envFile = process.env.NODE_ENV === 'test' ? '.env.test' : '.env';

    if (!fs.existsSync(envFile)) {
      throw new Error(`Environment file not found: ${envFile}`);
    }

    const lines = fs.readFileSync(envFile, 'utf8').split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;

      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=');

      // Check if value is encrypted (starts with ENC:)
      if (value.startsWith('ENC:')) {
        const decrypted = this.decrypt(value.substring(4));
        this.secrets.set(key.trim(), decrypted);
      } else {
        // Still store in Map, NOT process.env
        this.secrets.set(key.trim(), value);
      }
    }

    return this;
  }

  // Get secret value
  get(key) {
    return this.secrets.get(key);
  }

  // Verify all required secrets are present
  validate(requiredKeys) {
    const missing = requiredKeys.filter(key => !this.secrets.has(key));
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }
}

// Usage
const envLoader = new SecureEnvLoader();
await envLoader.load();

// Validate required secrets
envLoader.validate(['DATABASE_URL', 'JWT_SECRET']);

// Get secrets (NOT from process.env!)
const dbUrl = envLoader.get('DATABASE_URL');
const jwtSecret = envLoader.get('JWT_SECRET');

// Clear from memory when possible (JavaScript GC)
module.exports = envLoader;
