```javascript
// scripts/rotate-credentials.js
const fs = require('fs');
const crypto = require('crypto');

// Sanity check - refuse to run on production systems
if (process.env.NODE_ENV === 'production') {
  console.error('❌ Do NOT run rotation scripts directly in production');
  process.exit(1);
}

// Generate rotation checklist without exposing values
function generateRotationChecklist(envFile) {
  const content = fs.readFileSync(envFile, 'utf8');
  const lines = content.split('\n');

  const credentials = [];

  for (const line of lines) {
    const match = line.match(/^([A-Z_]+)=(.+)$/);
    if (match && !line.startsWith('#')) {
      const [, name, value] = match;

      // Categorize by service
      const service = categorizeService(name);
      const priority = getPriority(name);

      // Create unique tracking ID (hash of name, not the value)
      const trackId = crypto
        .createHash('sha256')
        .update(name)
        .digest('hex')
        .substring(0, 12);

      credentials.push({
        name,
        service,
        priority,
        trackId,
        length: value.length, // Just length, not content
        status: 'needs_rotation',
      });
    }
  }

  return credentials;
}

function categorizeService(variableName) {
  if (variableName.includes('AWS')) return 'AWS';
  if (variableName.includes('DATABASE')) return 'Database';
  if (variableName.includes('ANTHROPIC')) return 'Anthropic';
  if (variableName.includes('STRIPE')) return 'Stripe';
  if (variableName.includes('LOGFIRE')) return 'Logging';
  return 'Unknown';
}

function getPriority(variableName) {
  if (variableName.includes('SECRET') || variableName.includes('PASSWORD')) {
    return 'CRITICAL';
  }
  if (variableName.includes('KEY')) {
    return 'HIGH';
  }
  return 'MEDIUM';
}

