```javascript
// Track rotation via secret versions, not values
async function checkRotationStatus(secretName) {
  const AWS = require('aws-sdk');
  const secretsManager = new AWS.SecretsManager();

  const versions = await secretsManager.listSecretVersionIds({
    SecretId: secretName,
  }).promise();

  const versionsList = versions.Versions
    .filter(v => v.VersionStages.includes('AWSCURRENT'))
    .sort((a, b) => new Date(b.CreatedDate) - new Date(a.CreatedDate));

  return {
    secretName,
    currentVersion: versionsList[0]?.VersionId,
    lastRotated: versionsList[0]?.CreatedDate,
    rotationStatus: versionsList.length > 1 ? 'rotated' : 'initial',
  };
}
```

