```javascript
// scripts/submit-rotation-log.js
const crypto = require('crypto');
const fs = require('fs');
const http = require('http');

function hashCredential(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function generateSecureRotationLog(envFile) {
  const content = fs.readFileSync(envFile, 'utf8');
  const lines = content.split('\n');

  const credentials = [];

  for (const line of lines) {
    const match = line.match(/^([A-Z_]+)=(.+)$/);
    if (match && !line.startsWith('#')) {
      const [, name, value] = match;

      credentials.push({
        variableName: name,
        preRotationHash: hashCredential(value), // ONLY hash, not value
        service: categorizeService(name),
        priority: getPriority(name),
        timestamp: new Date().toISOString(),
      });
    }
  }

  return credentials;
}

function categorizeService(name) {
  if (name.includes('AWS')) return 'AWS';
  if (name.includes('DATABASE')) return 'Database';
  if (name.includes('ANTHROPIC')) return 'Anthropic';
  if (name.includes('STRIPE')) return 'Stripe';
  if (name.includes('LOGFIRE')) return 'LogFire';
  return 'Unknown';
}

function getPriority(name) {
  if (name.includes('SECRET') || name.includes('PASSWORD')) return 'CRITICAL';
  if (name.includes('KEY')) return 'HIGH';
  return 'MEDIUM';
}

function submitToComplianceWebhook(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify({
      credentials: data,
      metadata: {
        submittedBy: process.env.USER || 'system',
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development',
        note: 'Hash-based credentials only - actual values NOT transmitted',
      },
    });

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/rotation-log',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try {
          const response = JSON.parse(body) || {};
          resolve({
            statusCode: res.statusCode,
            response: response,
          });
        } catch (e) {
          resolve({ statusCode: res.statusCode, body: body });
        }
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

// Execute
async function main() {
  console.log('📋 Generating secure rotation log (hashes only)...');

  const secureLogData = generateSecureRotationLog('.env.test');

  console.log(`📊 Prepared ${secureLogData.length} credential entries for submission`);
  console.log('⚠️  Note: Only SHA-256 hashes are being transmitted, not actual secrets');

  try {
    console.log('📤 Submitting to compliance webhook...');
    const result = await submitToComplianceWebhook(secureLogData);

    if (result.statusCode >= 200 && result.statusCode < 300) {
      console.log(`✓ Submission successful (${result.statusCode})`);
      console.log('Response:', result.response);
    } else {
      console.log(`⚠️  Webhook returned status ${result.statusCode}`);
    }
  } catch (error) {
    console.error('❌ Submission failed:', error.message);
  }
}

main();
```

