// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const AWS = require('aws-sdk');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets to avoid unnecessary API calls
const secretsCache = new Map();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName, forceRefresh = false) {
  // Check cache first
  if (!forceRefresh && secretsCache.has(secretName)) {
    const cached = secretsCache.get(secretName);
    if (Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.value;
    }
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    let secret;
    if (response.SecretString) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString());
    }

    // Cache the secret
    secretsCache.set(secretName, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  } catch (error) {
    console.error(`Error fetching secret ${secretName}:`, error.message);
    throw new Error(`Failed to retrieve secret: ${secretName}`);
  }
}

// Initialize secrets on startup
async function loadSecrets() {
  try {
    const dbSecret = await getSecret('prod/database/credentials');
    const stripeSecret = await getSecret('prod/stripe/keys');
    const apiKeys = await getSecret('prod/api/keys');

