  const hasLower = /[a-z]/.test(value);
  const hasUpper = /[A-Z]/.test(value);
  const hasDigits = /\d/.test(value);
  const hasSpecial = /[^a-zA-Z0-9]/.test(value);

  return {
    length: value.length,
    characterClasses: {
      lowercase: hasLower,
      uppercase: hasUpper,
      digits: hasDigits,
      special: hasSpecial
    }
  };
}

