    }

    const value = process.env[name] || defaultValue;

    // DynamoDB-style redaction when accessing
    Object.defineProperty(this, name, {
      get: () => {
        return this.checkCache.get(name) || value;
      },
      enumerable: false,
      configurable: false
    });

    this.checkCache.set(name, value);
    return value;
  }

  /**
   * Check if secret is set without exposing value
   */
  has(name) {
    return this.checkCache.has(name) || process.env[name] !== undefined;
  }

  /**
   * Validate all required secrets
   */
  validate() {
    const errors = [];

    // Check required secrets
    for (const [name, config] of Object.entries(REQUIRED_SECRETS)) {
      const value = this.get(name);
      if (!value) {
        errors.push(`Missing required secret: ${name}`);
      } else if (config.validate && !config.validate(value)) {
        errors.push(`${name}: ${config.error}`);
      }
    }

    // Check optional secrets and log warnings
    for (const [name, description] of Object.entries(OPTIONAL_SECRETS)) {
      if (!this.has(name)) {
        console.warn(`⚠️  Optional secret not set: ${name} (${description})`);
      }
    }

    if (errors.length > 0) {
      console.error('\n🚨 Secrets validation failed:');
      errors.forEach(err => console.error(`  - ${err}`));
      process.exit(1);
    }

    console.log('✓ All required secrets validated');
  }

  /**
   * Redact secrets from objects (for logging)
   */
  redact(obj) {
    const redacted = { ...obj };
    const secretPatterns = [
      /password/i,
      /secret/i,
      /token/i,
      /key/i,
      /authorization/i
    ];

    for (const [key, value] of Object.entries(redacted)) {
      if (secretPatterns.some(pattern => pattern.test(key))) {
        redacted[key] = '[REDACTED]';
      } else if (typeof value === 'string' && value.length > 50) {
        // Long strings that might be secrets
        redacted[key] = value.substring(0, 10) + '...[REDACTED]';
      }
    }

    return redacted;
  }
}

// ===== Usage Example =====
function initSecrets() {
  console.log('\n🔐 Initializing Secrets Manager...\n');

  // Validate file permissions
  validateEnvFilePermissions();

  // Initialize secrets manager
  const secrets = new SecretsManager();

  // Validate required secrets
  secrets.validate();

  return secrets;
}

// ===== Integration with Express =====
function secureConfigMiddleware(secrets) {
  return (req, res, next) => {
    req.secrets = secrets;
    next();
  };
}

// Export for use in app
if (require.main === module) {
  // Running directly - test secrets loading
  try {
    const secrets = initSecrets();
    console.log('\n✓ Secrets loaded successfully');
    console.log('\nSecrets status:');
    console.log('  DATABASE_URL:', secrets.has('DATABASE_URL') ? '✓ Set' : '✗ Missing');
    console.log('  JWT_SECRET:', secrets.has('JWT_SECRET') ? '✓ Set' : '✗ Missing');
  } catch (err) {
    console.error('Failed to initialize secrets:', err.message);
    process.exit(1);
  }
}

module.exports = {
  SecretsManager,
  initSecrets,
  secureConfigMiddleware,
  REQUIRED_SECRETS,
  OPTIONAL_SECRETS
};

/**
 * PRODUCTION-GRADE SECRETS MANAGER
 * Supports multiple secrets backends with fallback support
 */

const AWS = require('aws-sdk');

class SecretsManager {
  constructor(options = {}) {
    this.backends = options.backends || ['aws-ssm', 'aws-secrets', 'env', 'file'];
    this.cache = new Map();
    this.cacheTimeout = options.cacheTimeout || 300000; // 5 minutes
  }

  /**
   * Load secret with multi-backend fallback
   */
  async getSecret(name, options = {}) {
    const { forceRefresh = false } = options;

    // Check cache
    if (!forceRefresh && this.cache.has(name)) {
      const cached = this.cache.get(name);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    // Try each backend
    for (const backend of this.backends) {
      try {
        const value = await this.loadFromBackend(backend, name);
        if (value) {
          this.cache.set(name, { value, timestamp: Date.now() });
          return value;
        }
      } catch (err) {
        continue; // Try next backend
      }
    }

    throw new Error(`Secret not found: ${name}`);
  }

  /**
   * Load from specific backend
   */
  async loadFromBackend(backend, name) {
    switch (backend) {
      case 'aws-ssm':
        return this.loadFromSSM(name);
      case 'aws-secrets':
        return this.loadFromSecretsManager(name);
      case 'env':
        return this.loadFromEnv(name);
      case 'file':
        return this.loadFromFile(name);
      default:
        throw new Error(`Unknown backend: ${backend}`);
    }
  }

  /**
   * AWS Systems Manager Parameter Store
   */
  async loadFromSSM(name) {
    const ssm = new AWS.SSM();
    const response = await ssm.getParameter({
      Name: name,
      WithDecryption: true
    }).promise();

    return response.Parameter.Value;
  }

  /**
   * AWS Secrets Manager
   */
  async loadFromSecretsManager(name) {
    const secretsManager = new AWS.SecretsManager();
    const response = await secretsManager.getSecretValue({
      SecretId: name
    }).promise();

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }
    return response.SecretBinary;
  }

  /**
   * Environment variables
   */
  loadFromEnv(name) {
    const value = process.env[name];
    if (!value) {
      throw new Error(`Environment variable not set: ${name}`);
    }
    return value;
  }

  /**
   * File-based (fallback for local dev only)
   */
  loadFromFile(name) {
    const fs = require('fs');
    const path = require('path');

    const secretsFile = path.join(process.cwd(), `.secrets.${process.env.NODE_ENV || 'dev'}.json`);

    if (!fs.existsSync(secretsFile)) {
      throw new Error('Secrets file not found');
    }

    const secrets = JSON.parse(fs.readFileSync(secretsFile, 'utf8'));
    return secrets[name];
  }

  /**
   * Bulk load multiple secrets
   */
  async loadSecrets(names) {
    const secrets = {};
    await Promise.all(
      names.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }

  /**
   * Clear cache (useful after secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Rotate a secret
   */
  async rotateSecret(name, newValue) {
    await this.storeSecret(name, newValue);
    this.cache.delete(name);
  }

  /**
   * Store secret
   */
  async storeSecret(name, value) {
    // Implementation depends on backend
    // Example for AWS Secrets Manager:
    const secretsManager = new AWS.SecretsManager();
    await secretsManager.putSecretValue({
      SecretId: name,
      SecretString: JSON.stringify(value)
    }).promise();
  }
}

module.exports = SecretsManager;

#!/usr/bin/env node
/**
 * PRE-STARTUP SECURITY CHECKS
 * Run before starting the application to verify security posture
 */

const fs = require('fs');
const path = require('path');

class SecurityAuditor {
  constructor() {
    this.issues = [];
    this.warnings = [];
  }

  /**
   * Run all security checks
   */
  audit() {
    console.log('\n🔒 Running Pre-Startup Security Audit...\n');

    this.checkEnvFiles();
    this.checkGitignore();
    this.checkSecretsInCode();
    this.checkDependencyLeaks();
    this.report();

    return this.issues.length === 0;
  }

  /**
   * Check for insecure .env files
   */
  checkEnvFiles() {
    const envFiles = ['.env', '.env.test', '.env.local', '.env.production'];
    const requiredPattern = /^-rw-------/; // 600 permissions

    for (const file of envFiles) {
      try {
        const stats = fs.statSync(file);
        const mode = stats.mode & 0o777;

        if (mode !== 0o600) {
          this.issues.push({
            type: 'CRITICAL',
            check: 'File Permissions',
            file,
            message: `${file} has insecure permissions: ${mode.toString(8)} (should be 600)`,
            fix: `chmod 600 ${file}`
          });
        } else {
          console.log(`✓ ${file}: Secure permissions (600)`);
        }

        // Check if secrets are hardcoded (not canary tokens)
        const content = fs.readFileSync(file, 'utf8');
        if (!content.includes('CANARY')) {
          this.warnings.push({
            type: 'WARNING',
            check: 'Production Secrets',
            file,
            message: `${file} may contain real production secrets`,
            recommendation: 'Move to secrets manager or verify these are canary tokens'
          });
        }
      } catch (err) {
        if (err.code === 'ENOENT') {
          continue; // File doesn't exist, skip
        }
        this.issues.push({
          type: 'ERROR',
          check: 'File Access',
          file,
          message: `Cannot read ${file}: ${err.message}`
        });
      }
    }
  }

  /**
   * Check if .gitignore exists and blocks secrets
   */
  checkGitignore() {
    const gitignorePath = '.gitignore';
    const requiredPatterns = ['.env', '.env.local', '*.key', '*.pem', 'credentials.json'];

    try {
      const gitignore = fs.readFileSync(gitignorePath, 'utf8');
      const missingPatterns = requiredPatterns.filter(
        pattern => !gitignore.includes(pattern)
      );

      if (missingPatterns.length > 0) {
        this.issues.push({
          type: 'CRITICAL',
          check: '.gitignore',
          file: gitignorePath,
          message: 'Missing patterns in .gitignore',
          details: missingPatterns,
          fix: 'Add missing patterns to .gitignore'
        });
      } else {
        console.log('✓ .gitignore: Contains all required patterns');
      }
    } catch (err) {
      this.issues.push({
        type: 'CRITICAL',
        check: '.gitignore',
        file: gitignorePath,
        message: '.gitignore not found',
        fix: 'Create .gitignore with .env and other secret files'
      });
    }
  }

  /**
   * Scan codebase for hardcoded secrets
   */
  checkSecretsInCode() {
    const secretPatterns = [
      /password\s*=\s*['"][^'"]{5,}['"]/gi,
      /secret\s*=\s*['"][^'"]{20,}['"]/gi,
      /api[_-]?key\s*=\s*['"][^'"]{15,}['"]/gi,
      /AKIA[0-9A-Z]{16}/g, // AWS Access Key pattern
      /sk[_-]?live[A-Za-z0-9]{30,}/g, // Stripe live key
    ];

    const codeFiles = ['app.js', 'server.js', 'index.js', 'config/**/*.js'];

    for (const pattern of codeFiles) {
      try {
        const content = fs.readFileSync(path.resolve(pattern), 'utf8');
        for (const secretPattern of secretPatterns) {
          const matches = content.match(secretPattern);
          if (matches) {
            this.issues.push({
              type: 'CRITICAL',
              check: 'Hardcoded Secrets',
              file: pattern,
              message: `Found potential hardcoded secrets`,
              pattern: secretPattern.source,
              fix: 'Move secrets to environment variables or secrets manager'
            });
          }
        }
      } catch (err) {
        // File doesn't exist, skip
      }
    }

    if (!this.issues.find(i => i.check === 'Hardcoded Secrets')) {
      console.log('✓ Code: No hardcoded secrets detected');
    }
  }

  /**
   * Check for package.json dependencies that leak environment
   */
  checkDependencyLeaks() {
    const packagejsonPath = 'package.json';

    try {
      const pkg = JSON.parse(fs.readFileSync(packagejsonPath, 'utf8'));
      const riskyDeps = ['dotenv-cli', 'dotenv-safe'];

      for (const dep of riskyDeps) {
        if (pkg.dependencies?.[dep] || pkg.devDependencies?.[dep]) {
          this.warnings.push({
            type: 'INFO',
            check: 'Dependencies',
            message: `${dep} is installed - ensure .env is in .gitignore`
          });
        }
      }

      console.log('✓ Dependencies: Checked');
    } catch (err) {
      // No package.json, skip
    }
  }

  /**
   * Print audit report
   */
  report() {
    console.log('\n' + '='.repeat(60));

    if (this.issues.length > 0) {
      console.log('🚨 CRITICAL SECURITY ISSUES FOUND:\n');

      for (const issue of this.issues) {
        const icon = issue.type === 'CRITICAL' ? '🔴' : '⚠️';
        console.log(`${icon} [${issue.type}] ${issue.check}`);
        console.log(`   File: ${issue.file}`);
        console.log(`   Message: ${issue.message}`);
        if (issue.details) {
          console.log(`   Missing patterns: ${issue.details.join(', ')}`);
        }
        if (issue.fix) {
          console.log(`   Fix: ${issue.fix}`);
        }
        console.log();
      }
    }

    if (this.warnings.length > 0) {
      console.log('⚠️  WARNINGS:\n');

      for (const warning of this.warnings) {
        console.log(`[${warning.type}] ${warning.check}`);
        console.log(`   ${warning.message}`);
        if (warning.recommendation) {
          console.log(`   Recommendation: ${warning.recommendation}`);
        }
        console.log();
      }
    }

    if (this.issues.length === 0 && this.warnings.length === 0) {
      console.log('✅ All security checks passed!\n');
    }

    console.log('='.repeat(60) + '\n');
  }
}

// Run audit if executed directly
if (require.main === module) {
  const auditor = new SecurityAuditor();
  const passed = auditor.audit();
  process.exit(passed ? 0 : 1);
}

module.exports = SecurityAuditor;

/**
 * SECURE APP WITH PROPER SECRETS MANAGEMENT
 * This is the production-ready version of app.js
 */

require('dotenv').config({ path: process.env.NODE_ENV === 'production' ? '.env.production' : '.env.test' });

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { createLogger, format, transports } = require('winston');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');
const { SecretsManager } = require('./secrets-manager');

// ============================================
// SECURITY: Validate .env file permissions
// ============================================
function validateEnvPermissions() {
  const envFile = process.env.NODE_ENV === 'production' ? '.env.production' : '.env.test';
  const envPath = path.resolve(envFile);

  try {
    const stats = fs.statSync(envPath);
    const mode = stats.mode & 0o777;

    if (mode !== 0o600) {
      console.error(`
╔══════════════════════════════════════════════════════════╗
║  🚨 SECURITY ALERT: Insecure .env file permissions! 🚨    ║
╠══════════════════════════════════════════════════════════╣
║  Current permissions: ${mode.toString(8).padEnd(42)}║
║  Required permissions: 600                               ║
╠══════════════════════════════════════════════════════════╣
║  Fix: chmod 600 ${envFile.padEnd(39)}║
╚══════════════════════════════════════════════════════════╝
      `);
      process.exit(1);
    }
  } catch (err) {
    if (err.code !== 'ENOENT') {
      console.error('Error checking .env permissions:', err.message);
      process.exit(1);
    }
  }
}

// Validate permissions on startup
validateEnvPermissions();

// ============================================
// LOGGER CONFIGURATION
// ============================================
const logger = createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: format.combine(
    format.timestamp(),
    format.printf(({ timestamp, level, message, ...meta }) => {
      // Redact sensitive data
      const sanitized = JSON.stringify(meta, (key, value) => {
        const sensitiveKeys = /password|secret|token|key|authorization/i;
        if (sensitiveKeys.test(key)) return '[REDACTED]';
        return value;
      });
      return `${timestamp} [${level.toUpperCase()}]: ${message} ${sanitized}`;
    })
  ),
  transports: [
    new transports.Console({ format: format.simple() }),
    new transports.File({ filename: 'logs/error.log', level: 'error' }),
    new transports.File({ filename: 'logs/combined.log' })
  ]
});

// ============================================
// APP INITIALIZATION
// ============================================
const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true
}));
app.disable('x-powered-by');

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests' }
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// HTTP request logging
app.use(morgan('combined', { stream: { write: msg => logger.info(msg.trim()) } }));

// ============================================
// REDACTED DATABASE URL
// ============================================
function getRedactedDatabaseUrl() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) return null;

  try {
    const url = new URL(dbUrl);
    url.password = '***REDACTED***';
    return url.toString();
  } catch {
    return '[INVALID DATABASE URL - PARSE ERROR]';
  }
}

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
    database: getRedactedDatabaseUrl() ? 'connected' : 'not configured'
  });
});

app.get('/config-status', (req, res) => {
  // Only show status, never actual secrets
  res.json({
    environment: process.env.NODE_ENV,
    configured_secrets: {
      database_url: !!process.env.DATABASE_URL,
      jwt_secret: !!process.env.JWT_SECRET,
      aws_configured: !!(process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY),
      stripe_configured: !!process.env.STRIPE_SECRET_KEY
    },
    security: {
      env_file_permissions: '600',
      rate_limiting: 'enabled',
      helment_security: 'enabled'
    }
  });
});

// ============================================
// ERROR HANDLING
// ============================================
app.use((err, req, res, next) => {
  logger.error('Application error:', { error: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal Server Error' });
});

// ============================================
// SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV}`);
  logger.info(`Database: ${getRedactedDatabaseUrl()}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

