#!/usr/bin/env node
/**
 * SECURE ROTATION LOG GENERATOR
 * Creates a rotation log with cryptographic hashes instead of cleartext secrets
 */

const crypto = require('crypto');
const fs = require('fs');

// Read current .env file
function readEnvFile() {
  try {
    const envFile = process.env.ENV_FILE || '.env.test';
    const content = fs.readFileSync(envFile, 'utf8');
    return content;
  } catch (err) {
    console.error('Error reading environment file:', err.message);
    process.exit(1);
  }
}

// Parse environment variables
function parseEnvVariables(content) {
  const variables = {};
  const lines = content.split('\n');

  lines.forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const match = line.match(/^([A-Z_]+)=(.+)$/);
    if (match) {
      variables[match[1]] = match[2];
    }
  });

  return variables;
}

// Generate SHA-256 hash of value
function hashValue(value) {
  return crypto.createHash('sha256').update(value, 'utf8').digest('hex');
}

// Generate secure rotation log (NO cleartext secrets)
function generateSecureRotationLog(variables) {
  const log = {
    generated_at: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    verification_type: 'CRYPTOGRAPHIC_HASH_ONLY',
    note: 'This log contains only cryptographic hashes for verification. No cleartext secrets are stored.',
    credentials: {}
  };

  for (const [name, value] of Object.entries(variables)) {
    const valuePreview = value.length <= 10 ? value : `${value.substring(0, 6)}...${value.substring(value.length - 4)}`;

    log.credentials[name] = {
      pre_rotation: {
        sha256_hash: hashValue(value),
        length: value.length,
        first_chars: value.substring(0, 4),
        last_chars: value.substring(value.length - 4),
        preview: valuePreview
      }
    };
  }

  return log;
}

// Write rotation log
function writeRotationLog(logData, filename) {
  const filepath = filename || 'rotation-log.secure.json';
  fs.writeFileSync(filepath, JSON.stringify(logData, null, 2), { mode: 0o600 });
  console.log(`✓ Secure rotation log written to: ${filepath}`);
  console.log(`✓ File permissions set to: 600`);

  // Add to .gitignore to ensure it's not committed
  try {
    const gitignorePath = '.gitignore';
    let gitignoreContent = '';

    try {
      gitignoreContent = fs.readFileSync(gitignorePath, 'utf8');
    } catch (err) {
      // File doesn't exist yet
    }

    if (!gitignoreContent.includes('rotation-log*.json') && !gitignoreContent.includes('rotation-log*.secure.json')) {
      gitignoreContent += '\n# Rotation logs (contain credential hashes)\nrotation-log*.secure.json\n';
      fs.writeFileSync(gitignorePath, gitignoreContent);
      console.log('✓ Added rotation-log*.secure.json to .gitignore');
    }
  } catch (err) {
    console.warn('Warning: Could not update .gitignore:', err.message);
  }
}

// Verification function (to be used after rotation)
function verifyRotation(credentialName, newValue) {
  try {
    const logData = JSON.parse(fs.readFileSync('rotation-log.secure.json', 'utf8'));
    const oldHash = logData.credentials[credentialName]?.pre_rotation?.sha256_hash;
    const newHash = hashValue(newValue);

    return {
      credential: credentialName,
      old_hash: oldHash,
      new_hash: newHash,
      verified: oldHash !== newHash,
      message: oldHash === newHash
        ? 'FAILED: Credential was NOT rotated (hashes match)'
        : 'SUCCESS: Credential has been rotated (hashes differ)'
    };
  } catch (err) {
    return { error: err.message };
  }
}

// CLI interface
if (require.main === module) {
  const args = process.argv.slice(2);
  const command = args[0];

  switch (command) {
    case 'create':
      const envContent = readEnvFile();
      const variables = parseEnvVariables(envContent);
      const logData = generateSecureRotationLog(variables);
      writeRotationLog(logData, args[1]);

      console.log('\n=== CREDENTIALS TRACKED ===');
      Object.keys(variables).forEach((name, idx) => {
        console.log(`${idx + 1}. ${name}`);
      });
      console.log(`\nTotal: ${Object.keys(variables).length} credentials`);
      break;

    case 'verify':
      const name = args[1];
      const newValue = args[2];
      if (!name || !newValue) {
        console.error('Usage: node create-rotation-log.js verify <credential-name> <new-value>');
        process.exit(1);
      }
      const result = verifyRotation(name, newValue);
      console.log(JSON.stringify(result, null, 2));
      break;

    case 'example':
      console.log(`
SECURE ROTATION LOG USAGE:

1. Generate rotation log (hashes only, no cleartext):
   node create-rotation-log.js create [filename]

2. Verify a credential was rotated:
   node create-rotation-log.js verify DATABASE_URL "postgresql://user:newpass@host/db"

3. The log format (JSON):
   {
     "generated_at": "2024-01-...",
     "environment": "production",
     "verification_type": "CRYPTOGRAPHIC_HASH_ONLY",
     "credentials": {
       "DATABASE_URL": {
         "pre_rotation": {
           "sha256_hash": "abc123...",
           "length": 67,
           "first_chars": "post",
           "last_chars": "tion",
           "preview": "post...tion"
         }
       }
     }
   }

This allows verification without storing cleartext secrets!
      `);
      break;

    default:
      console.error(`
Usage: node create-rotation-log.js <command> [args]

Commands:
  create [filename]  - Generate secure rotation log (hashes only)
  verify <name> <new-value> - Verify a credential was rotated
  example           - Show usage examples
      `);
      process.exit(1);
  }
}

module.exports = {
  generateSecureRotationLog,
  verifyRotation,
  hashValue
};

