#!/usr/bin/env node
/**
 * ROTATION VERIFICATION HELPER
 * Use this after rotating credentials to verify the rotation was successful
 */

const fs = require('fs');
const crypto = require('crypto');

function hashValue(value) {
  return crypto.createHash('sha256').update(value, 'utf8').digest('hex');
}

function verifyRotation(credentialName, newValue, logFile = 'rotation-log.secure.json') {
  try {
    const logData = JSON.parse(fs.readFileSync(logFile, 'utf8'));
    const credential = logData.credentials[credentialName];

    if (!credential) {
      return {
        success: false,
        error: `Credential ${credentialName} not found in rotation log`
      };
    }

    const oldHash = credential.pre_rotation.sha256_hash;
    const newHash = hashValue(newValue);
    const wasRotated = oldHash !== newHash;

    return {
      success: true,
      credential: credentialName,
      old_hash: oldHash,
      new_hash: newHash,
      verified: wasRotated,
      result: wasRotated ? '✓ ROTATED SUCCESSFULLY' : '✗ NOT ROTATED (hashes match)'
    };
  } catch (err) {
    return {
      success: false,
      error: err.message
    };
  }
}

function showUsage() {
  console.log(`
ROTATION VERIFICATION HELPER

Usage:
  node rotation-helper.js verify <credential-name> <new-value>

Examples:
  # Verify DATABASE_URL was rotated
  node rotation-helper.js verify DATABASE_URL "postgresql://admin:newpass@host:5432/db"

  # Verify API key was rotated
  node rotation-helper.js verify STRIPE_SECRET_KEY "sk-live-new_secret_key_here"

The script will compare the SHA-256 hash of the new value against
the pre-rotation hash stored in rotation-log.secure.json.
  `);
}

if (require.main === module) {
  const args = process.argv.slice(2);

  if (args.length < 3 || args[0] !== 'verify') {
    showUsage();
    process.exit(1);
  }

  const result = verifyRotation(args[1], args[2]);

  if (result.success) {
    console.log('\n=== ROTATION VERIFICATION ===');
    console.log(`Credential: ${result.credential}`);
    console.log(`Old hash:   ${result.old_hash.substring(0, 16)}...`);
    console.log(`New hash:   ${result.new_hash.substring(0, 16)}...`);
    console.log(`\nResult:     ${result.result}`);
    console.log('='.repeat(40) + '\n');
    process.exit(result.verified ? 0 : 1);
  } else {
    console.error(`Error: ${result.error}`);
    process.exit(1);
  }
}

module.exports = { verifyRotation, hashValue };

