```

---

### 7. **No CORS Configuration**
**OWASP Category:** A01:2021 – Broken Access Control

Missing CORS controls allows any origin to make requests to your API.

**Recommended Fix:**
```javascript
const cors = require('cors'); // npm install cors

// Whitelist specific origins
const allowedOrigins = [
  'https://yourdomain.com',
  'https://app.yourdomain.com'
];

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

---

### 8. **Sensitive Data Exposure via .env File**
**OWASP Category:** A02:2021 – Cryptographic Failures, A05:2021 – Security Misconfiguration

The `.env.test` file contains sensitive credentials and should not be committed or accessible.

**Current `package.json` dependencies issue:**
No `.gitignore` or `.env` management strategy is evident.

**Recommended Fix:**

1. **Create a `.gitignore` file:**
```gitignore
# Environment variables
.env
.env.local
.env.*.local

# Node modules
node_modules/

# Logs
logs/
*.log
npm-debug.log*

# OS files
.DS_Store
Thumbs.db
```

2. **Use environment-specific config:**
```javascript
require('dotenv').config(); // npm install dotenv

// Validate required environment variables
const requiredEnvVars = [
  'DATABASE_URL',
  'JWT_SECRET',
  'NODE_ENV'
];

const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
}

// Configuration object
const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  database: {
    url: process.env.DATABASE_URL
  },
  jwt: {
    secret: process.env.JWT_SECRET,
    expiresIn: process.env.JWT_EXPIRES_IN || '1h'
  }
};

module.exports = config;
```

3. **Never commit real secrets** - use placeholder values in committed `.env.example`:
```bash
# .env.example (safe to commit)
DATABASE_URL=postgresql://user:password@localhost:5432/dbname
JWT_SECRET=your-secret-key-here
NODE_ENV=development
```

---

### 9. **No Request Size Limits (DoS Vulnerability)**
**OWASP Category:** A04:2021 – Insecure Design

Large payloads can exhaust server memory.

**Recommended Fix:**
```javascript
app.use(express.json({ limit: '1mb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '1mb' })); // Limit URL-encoded body
```

---

### 10. **Missing Health Check Hardening**
**OWASP Category:** A01:2021 – Broken Access Control

The `/health` endpoint could be exploited for reconnaissance or timing attacks.

**Recommended Fix:**
```javascript
// Rate-limited health check
const healthLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 10,
  skipSuccessfulRequests: true
});

app.get('/health', healthLimiter, (req, res) => {
  res.status(200).json({ 
    status: 'ok',
    // Remove timestamp to prevent side-channel attacks
    // or use generalized response
  });
});
```

---

## 📋 Complete Secure Implementation Example

Here's a comprehensive secure version of `app.js`:

```javascript
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ==================== Security Middleware ====================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Request size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Disable X-Powered-By header
app.disable('x-powered-by');

// ==================== Request ID ====================

const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ==================== Validation Middleware ====================

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      requestId: req.id
    });
  }
  next();
};

// ==================== Authentication Middleware ====================

const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      requestId: req.id
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        requestId: req.id
      });
    }
    req.user = user;
    next();
  });
};

const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        requestId: req.id
      });
    }
    next();
  };
};

// ==================== Routes ====================

const healthLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 10
});

app.get('/health', healthLimiter, (req, res) => {
  res.json({ status: 'healthy' });
});

// Example: Protected user endpoint
app.get('/users', authenticate, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// Example: Input with validation
app.post('/users',
  body('email').isEmail().normalizeEmail(),
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  validate,
  authenticate,
  (req, res) => {
    res.status(201).json({ message: 'User created' });
  }
);

// ==================== Error Handling ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    requestId: req.id
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[Error] Request ID: ${req.id}`, err);

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(status).json({ 
    error: message,
    requestId: req.id
  });
});

// ==================== Server ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;
```

