/**
 * SECURE CONFIGURATION LOADER EXAMPLE
 *
 * This file demonstrates a production-ready approach to loading secrets
 * with proper validation and multiple source support.
 */

// ============================================================================
// ENVIRONMENT VARIABLE VALIDATION
// ============================================================================

const requiredEnvVars = {
  // Database
  DATABASE_URL: 'Database connection URL is required',

  // Security
  JWT_SECRET: 'JWT secret is required (min 32 characters)',
  JWT_EXPIRES_IN: 'JWT expiration time is required',

  // Application
  NODE_ENV: 'NODE_ENV is required (development|staging|production)',
  PORT: 'PORT is required'
};

const optionalEnvVars = {
  // AWS (optional if using other cloud providers)
  AWS_ACCESS_KEY_ID: null,
  AWS_SECRET_ACCESS_KEY: null,
  AWS_REGION: 'us-east-1',

  // Third-party services
  ANTHROPIC_API_KEY: null,
  STRIPE_SECRET_KEY: null,
  LOGFIRE_TOKEN: null,

  // Feature flags
  ENABLE_DEBUG_LOGGING: 'false',
  ENABLE_METRICS: 'true',

  // CORS
  ALLOWED_ORIGINS: 'http://localhost:3000'
};

// ============================================================================
// VALIDATION FUNCTIONS
// ============================================================================

const isValidJwtSecret = (secret) => {
  return typeof secret === 'string' && secret.length >= 32;
};

const isValidNodeEnv = (value) => {
  return ['development', 'staging', 'production'].includes(value);
};

const isValidUrl = (url) => {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
};

// ============================================================================
// CONFIGURATION VALIDATION
// ============================================================================

function validateConfig(env) {
  const errors = [];
  const warnings = [];

  // Check required variables
  Object.entries(requiredEnvVars).forEach(([key, errorMessage]) => {
    if (!env[key]) {
      errors.push(`Missing required environment variable: ${key}`);
    }
  });

  // Type/format validation
  if (env.JWT_SECRET && !isValidJwtSecret(env.JWT_SECRET)) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  if (env.NODE_ENV && !isValidNodeEnv(env.NODE_ENV)) {
    errors.push('NODE_ENV must be development, staging, or production');
  }

  if (env.DATABASE_URL && !isValidUrl(env.DATABASE_URL)) {
    errors.push('DATABASE_URL must be a valid URL');
  }

  // Security warnings
  if (env.NODE_ENV === 'production') {
    if (env.JWT_SECRET === 'change-me-in-production') {
      warnings.push('Using default JWT_SECRET in production!');
    }
    if (env.JWT_SECRET?.length < 64) {
      warnings.push('JWT_SECRET should be at least 64 characters in production');
    }
  }

  return { errors, warnings };
}

// ============================================================================
// LOAD CONFIGURATION WITH SOURCE PRIORITY
// ============================================================================

function loadConfig() {
  // Priority order: Secrets Manager > .env.production > .env > process.env > defaults

  let env = { ...process.env };

  // Load environment-specific .env file
  const envFile = `.env.${env.NODE_ENV || 'development'}`;
  try {
    require('dotenv').config({ path: envFile });
    env = { ...env, ...process.env };
  } catch (e) {
    // dotenv not available or file doesn't exist
  }

  // Add optional defaults
  Object.entries(optionalEnvVars).forEach(([key, defaultValue]) => {
    if (!env[key] && defaultValue) {
      env[key] = defaultValue;
    }
  });

  return env;
}

// ============================================================================
// BUILD CONFIGURATION OBJECT
// ============================================================================

const env = loadConfig();
const validation = validateConfig(env);

// Log warnings
if (validation.warnings.length > 0) {
  console.warn('Configuration warnings:');
  validation.warnings.forEach(w => console.warn(`  ⚠️  ${w}`));
}

// Throw on errors
if (validation.errors.length > 0) {
  throw new Error(`Configuration validation failed:\n${validation.errors.map(e => `  - ${e}`).join('\n')}`);
}

// ============================================================================
// EXPORTED CONFIGURATION
// ============================================================================

const config = {
  // Environment
  env: env.NODE_ENV,
  isDevelopment: env.NODE_ENV === 'development',
  isStaging: env.NODE_ENV === 'staging',
  isProduction: env.NODE_ENV === 'production',

  // Server
  port: parseInt(env.PORT, 10),

  // Database
  database: {
    url: env.DATABASE_URL
  },

  // Security
  security: {
    jwt: {
      secret: env.JWT_SECRET,
      expiresIn: env.JWT_EXPIRES_IN || '1h'
    },
    bcryptRounds: env.isProduction ? 12 : 10
  },

  // Cloud Provider
  aws: {
    accessKeyId: env.AWS_ACCESS_KEY_ID,
    secretAccessKey: env.AWS_SECRET_ACCESS_KEY,
    region: env.AWS_REGION || 'us-east-1',
    enabled: !!(env.AWS_ACCESS_KEY_ID && env.AWS_SECRET_ACCESS_KEY)
  },

  // Third-party Services
  services: {
    anthropic: {
      apiKey: env.ANTHROPIC_API_KEY,
      enabled: !!env.ANTHROPIC_API_KEY
    },
    stripe: {
      secretKey: env.STRIPE_SECRET_KEY,
      enabled: !!env.STRIPE_SECRET_KEY
    },
    logfire: {
      token: env.LOGFIRE_TOKEN,
      enabled: !!env.LOGFIRE_TOKEN
    }
  },

  // Feature Flags
  features: {
    debugLogging: env.ENABLE_DEBUG_LOGGING === 'true',
    metrics: env.ENABLE_METRICS !== 'false'
  },

  // CORS
  cors: {
    allowedOrigins: env.ALLOWED_ORIGINS ? env.ALLOWED_ORIGINS.split(',') : ['*']
  }
};

// Freeze configuration in production
if (config.isProduction) {
  Object.freeze(config);
}

module.exports = config;

/**
 * PRODUCTION SECRETS MANAGER INTEGRATION
 *
 * This file demonstrates integration with AWS Secrets Manager and
 * HashiCorp Vault for production-grade secret management.
 */

const AWS = require('aws-sdk');

// ============================================================================
// AWS SECRETS MANAGER CLIENT
// ============================================================================

class SecretsManager {
  constructor() {
    this.secretCache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
    this.provider = process.env.SECRETS_PROVIDER || 'local';
  }

  /**
   * Retrieve a secret with caching
   */
  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    const cached = this.secretCache.get(secretName);
    if (!forceRefresh && cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    // Fetch from provider
    const secret = await this._fetchFromProvider(secretName);

    // Cache the result
    this.secretCache.set(secretName, {
      value: secret,
      expiresAt: Date.now() + this.cacheTTL
    });

    return secret;
  }

  /**
   * Fetch secret from configured provider
   */
  async _fetchFromProvider(secretName) {
    switch (this.provider) {
      case 'aws':
        return this._getFromAwsSecretsManager(secretName);
      case 'vault':
        return this._getFromHashiCorpVault(secretName);
      case 'gcp':
        return this._getFromGCPSecretManager(secretName);
      case 'azure':
        return this._getFromAzureKeyVault(secretName);
      case 'local':
      default:
        return this._getFromEnvironment(secretName);
    }
  }

  /**
   * AWS Secrets Manager
   */
  async _getFromAwsSecretsManager(secretName) {
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in response) {
        return JSON.parse(response.SecretString);
      } else {
        return Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        // Fall back to environment variable
        console.warn(`Secret "${secretName}" not found in AWS, checking environment`);
        return this._getFromEnvironment(secretName);
      }
      throw error;
    }
  }

  /**
   * HashiCorp Vault
   */
  async _getFromHashiCorpVault(secretName) {
    const axios = require('axios');
    const vaultUrl = process.env.VAULT_ADDR || 'http://localhost:8200';
    const roleId = process.env.VAULT_ROLE_ID;
    const secretId = process.env.VAULT_SECRET_ID;

    try {
      // AppRole authentication
      const authResponse = await axios.post(`${vaultUrl}/v1/auth/approle/login`, {
        role_id: roleId,
        secret_id: secretId
      });

      const token = authResponse.data.auth.client_token;

      // Fetch secret
      const secretPath = secretName.replace(/^vault:/, 'secret/data/');
      const secretResponse = await axios.get(
        `${vaultUrl}/v1/${secretPath}`,
        {
          headers: { 'X-Vault-Token': token }
        }
      );

      return secretResponse.data.data.data;
    } catch (error) {
      console.error('Vault fetch error:', error.message);
      throw new Error(`Failed to fetch secret from Vault: ${secretName}`);
    }
  }

  /**
   * Google Cloud Secret Manager
   */
  async _getFromGCPSecretManager(secretName) {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

    const client = new SecretManagerServiceClient();
    const name = secretName.replace(/^gcp:/, 'projects/*/secrets/') + '/versions/latest';

    try {
      const [version] = await client.accessSecretVersion({ name });
      const payload = version.payload.data.toString('utf8');
      return JSON.parse(payload);
    } catch (error) {
      console.error('GCP Secret Manager error:', error.message);
      throw new Error(`Failed to fetch secret from GCP: ${secretName}`);
    }
  }

  /**
   * Azure Key Vault
   */
  async _getFromAzureKeyVault(secretName) {
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const vaultUrl = process.env.AZURE_KEYVAULT_URL;
    const credential = new DefaultAzureCredential();
    const client = new SecretClient(vaultUrl, credential);

    try {
      const secretNameOnly = secretName.replace(/^azure:/, '');
      const secret = await client.getSecret(secretNameOnly);
      return JSON.parse(secret.value);
    } catch (error) {
      console.error('Azure Key Vault error:', error.message);
      throw new Error(`Failed to fetch secret from Azure: ${secretName}`);
    }
  }

  /**
   * Environment variables (fallback/local dev)
   */
  _getFromEnvironment(secretName) {
    const envVarName = secretName.toUpperCase().replace(/[^A-Z0-9]/g, '_');

    if (!process.env[envVarName]) {
      throw new Error(`Environment variable not found: ${envVarName}`);
    }

    return process.env[envVarName];
  }

  /**
   * Load multiple secrets
   */
  async loadMany(secretNames) {
    const secrets = {};
    const promises = secretNames.map(async (name) => {
      secrets[name] = await this.getSecret(name);
    });
    await Promise.all(promises);
    return secrets;
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.secretCache.clear();
  }

  /**
   * Rotate secret (if provider supports)
   */
  async rotateSecret(secretName, newSecretValue) {
    switch (this.provider) {
      case 'aws':
        return this._rotateAwsSecret(secretName, newSecretValue);
      default:
        throw new Error('Secret rotation not implemented for this provider');
    }
  }

  async _rotateAwsSecret(secretName, newSecretValue) {
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    await client.putSecretValue({
      SecretId: secretName,
      SecretString: JSON.stringify(newSecretValue)
    }).promise();

    // Clear cache
    this.secretCache.delete(secretName);

    return true;
  }
}

// ============================================================================
// CONFIGURATION LOADER WITH SECRETS MANAGER
// ============================================================================

async function loadProductionConfig() {
  const secretsManager = new SecretsManager();

  // Define required secrets
  const secretMappings = {
    database: {
      aws: 'production/database',
      env: 'DATABASE_URL'
    },
    jwt: {
      aws: 'production/jwt',
      env: 'JWT_SECRET'
    },
    stripe: {
      aws: 'production/stripe',
      env: 'STRIPE_SECRET_KEY'
    },
    anthropic: {
      aws: 'production/anthropic',
      env: 'ANTHROPIC_API_KEY'
    }
  };

  // Load secrets
  const secrets = {};
  for (const [key, mapping] of Object.entries(secretMappings)) {
    try {
      secrets[key] = await secretsManager.getSecret(mapping[secretsManager.provider] || `${secretsManager.provider}:${mapping.aws}`);
    } catch (error) {
      console.error(`Failed to load secret "${key}":`, error.message);
      throw error;
    }
  }

  // Build configuration
  return {
    env: process.env.NODE_ENV,
    port: parseInt(process.env.PORT, 10),

    database: {
      url: secrets.database
    },

    security: {
      jwt: {
        secret: secrets.jwt,
        expiresIn: process.env.JWT_EXPIRES_IN || '1h'
      }
    },

    services: {
      stripe: {
        secretKey: secrets.stripe
      },
      anthropic: {
        apiKey: secrets.anthropic
      }
    }
  };
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = {
  SecretsManager,
  loadProductionConfig
};

