### Option 1: AWS Secrets Manager (Production-Grade)

```javascript
// secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

const getSecret = async (secretName) => {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    // Binary secret
    return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
  } catch (error) {
    throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
  }
};

const loadSecrets = async () => {
  const secrets = await getSecret(process.env.SECRET_ARN || 'myapp/production');

  // Map secrets to process.env
  process.env.DATABASE_URL = secrets.database_url;
  process.env.AWS_ACCESS_KEY_ID = secrets.aws_access_key_id;
  process.env.AWS_SECRET_ACCESS_KEY = secrets.aws_secret_access_key;
  process.env.STRIPE_SECRET_KEY = secrets.stripe_secret_key;
  process.env.ANTHROPIC_API_KEY = secrets.anthropic_api_key;
  process.env.LOGFIRE_TOKEN = secrets.logfire_token;

  return secrets;
};

module.exports = { loadSecrets, getSecret };
```

