// parameter-store.js
const AWS = require('aws-sdk');
const ssm = new AWS.SSM({ region: process.env.AWS_REGION });

const loadParameters = async () => {
  const parameters = [
    '/myapp/database/url',
    '/myapp/stripe/secret-key',
    '/myapp/anthropic/api-key',
    '/myapp/logfire/token'
