  AWS_ACCESS_KEY_ID: Joi.string().min(16).max(128),
  AWS_SECRET_ACCESS_KEY: Joi.string().min(16).max(128),

  // API Keys
  ANTHROPIC_API_KEY: Joi.string().pattern(/^sk-ant-/),
