  PORT: Joi.number().port().default(3000),
  API_KEY: Joi.string().min(32).required(),

  // Security
  ALLOWED_ORIGINS: Joi.string().default('http://localhost:3000'),
  LOG_LEVEL: Joi.string().valid('error', 'warn', 'info', 'debug').default('info'),
});

// Validate and export
const { error, value: secrets } = secretsSchema.validate(process.env, {
  stripUnknown: true,
  allowUnknown: false
});

if (error) {
  throw new Error(`Configuration validation error: ${error.details[0].message}`);
}

// Detect canary values in production and fail
