  const canaryPatterns = /CANARY|test|example|placeholder/i;
  Object.entries(secrets).forEach(([key, value]) => {
    if (typeof value === 'string' && canaryPatterns.test(value)) {
      throw new Error(`CRITICAL: Canary/test value detected in production for ${key}`);
    }
  });
}

module.exports = secrets;
