#!/bin/bash
# .git/hooks/pre-commit

# Check for accidental secret commits
SECRETS_PATTERN='(password|secret|api[_-]?key|access[_-]?key):.*[^\s]{8,}'

if git diff --cached --name-only | grep -E '\.(js|json|env|yml|yaml)$' | \
   xargs grep -i -E "$SECRETS_PATTERN"; then
  echo "❌ Potential secrets detected in staged files!"
  echo "Please remove sensitive data before committing."
  exit 1
fi

# Check for actual secret values in .env files
if git diff --cached --name-only | grep -E '\.env$' | \
   xargs grep -v -E '^(#|$)' | grep -v -E '^(NODE_ENV|PORT|LOG_LEVEL)='; then
  echo "❌ Only TEMPLATE .env files should be committed!"
  echo "Use .env.example instead."
  exit 1
fi

echo "✅ Pre-commit checks passed"
