### 5. **Runtime Secret Validation**
```javascript
// middleware/validate-secrets.js
module.exports = function validateSecretsOnStartup(secrets) {
  const issues = [];

  // Check for canary/test values in production
  if (secrets.NODE_ENV === 'production') {
    const canaryPatterns = [
      /CANARY/i,
      /test/i,
      /example/i,
      /placeholder/i,
      /xxx/i,
      /^123/,
      /^abc/
    ];

    Object.entries(secrets).forEach(([key, value]) => {
      if (typeof value === 'string' && value.length > 0) {
        if (canaryPatterns.some(pattern => pattern.test(value))) {
          issues.push(`${key}: appears to be a test/canary value`);
        }
      }
    });
  }

  // Check secret complexity
  const weakPatterns = [
    { pattern: /^.{0,8}$/, message: 'too short (< 8 chars)' },
    { pattern: /^(password|123456|qwerty|admin)/i, message: 'common weak value' }
  ];

  const secretKeys = ['API_KEY', 'AWS_SECRET_ACCESS_KEY', 'DATABASE_URL'];
  secretKeys.forEach(key => {
    if (secrets[key]) {
      weakPatterns.forEach(({ pattern, message }) => {
        if (pattern.test(secrets[key])) {
          issues.push(`${key}: ${message}`);
        }
      });
    }
  });

  if (issues.length > 0) {
    const error = new Error('Secret validation failed:\n' + 
      issues.map(i => `  - ${i}`).join('\n'));
    error.code = 'SECRETS_VALIDATION_ERROR';
    throw error;
  }

  console.log('✅ All secrets validated successfully');
};
```

