### 9. SSRF Protection (Future Risk)
**Risk Level:** 🟡 LOW  
**OWASP Category:** A10:2021 - Server-Side Request Forgery

**Current State:** No URL validation (relevant for future features).

**Impact:** Attackers could force server to access internal resources.

**Fix:**
```javascript
const dns = require('dns').promises;
const net = require('net');

const isPrivateIP = (ip) => {
  const blocks = [
    ['10.0.0.0', '10.255.255.255'],
    ['172.16.0.0', '172.31.255.255'],
    ['192.168.0.0', '192.168.255.255'],
    ['127.0.0.0', '127.255.255.255'],
  ];

  return blocks.some(([start, end]) => {
    const ipNum = ip.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet), 0) >>> 0;
    const startNum = start.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet), 0) >>> 0;
    const endNum = end.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet), 0) >>> 0;
    return ipNum >= startNum && ipNum <= endNum;
  });
};

const validateUrl = async (urlString) => {
  const url = new URL(urlString);

  // Resolve hostname to IP
  const { address } = await dns.lookup(url.hostname);

  if (isPrivateIP(address)) {
    throw new Error('Access to private IPs is not allowed');
  }

  if (!['http:', 'https:'].includes(url.protocol)) {
    throw new Error('Only HTTP/HTTPS URLs are allowed');
  }

  return true;
};
```

