# Quick Security Code Patterns for app.js

## Essential Security Middleware Setup

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// 1. Security Headers ( ALWAYS FIRST)
app.use(helmet());

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests'
});
app.use('/api', limiter);

// 3. Body Size Limits
app.use(express.json({ limit: '10kb' }));

// 4. Trust Proxy (for SSL detection)
app.set('trust proxy', 1);
```

---

## Authentication Pattern

```javascript
const jwt = require('jsonwebtoken');

// Middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// Usage
app.get('/protected', authenticate, (req, res) => {
  res.json({ user: req.user });
});
```

---

## Input Validation Pattern

```javascript
const { body, query, validationResult } = require('express-validator');

const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Usage
app.post('/users',
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).matches(/[A-Z]/).matches(/[0-9]/),
  validate,
  (req, res) => {
    // Validated data in req.body
  }
);
```

---

## Async Error Handler Pattern

```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/users', asyncHandler(async (req, res) => {
  const users = await User.findAll();
  res.json(users);
}));

// Global error handler (last middleware)
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: {
      message: isDev ? err.message : 'Internal Server Error'
    }
  });
});
```

---

## Secure Database Query Pattern

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false
});

// ✅ CORRECT - Parameterized query
async function getUser(id) {
  const result = await pool.query(
    'SELECT * FROM users WHERE id = $1',
    [id]
  );
  return result.rows[0];
}

// ❌ WRONG - SQL Injection vulnerability
async function getUserBad(id) {
  const result = await pool.query(
    `SELECT * FROM users WHERE id = ${id}`
  );
  return result.rows[0];
}
```

