### Option 2: For Production (Secrets Manager)

```javascript
// config.js - Production-ready
const AWS = require('aws-sdk');

class SecretManager {
  constructor() {
    this.client = new AWS.SecretsManager({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    const cacheKey = secretName;

    // Return cached value if valid
    const cached = this.cache.get(cacheKey);
    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      const secret = data.SecretString ? JSON.parse(data.SecretString) : data.SecretBinary;

      // Cache the result
      this.cache.set(cacheKey, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }
}

const secrets = new SecretManager();

// Configuration loader
async function loadConfig() {
  const secretsPrefix = `myapp/${process.env.NODE_ENV}`;

  return {
    database: {
      url: await secrets.getSecret(`${secretsPrefix}/database/url`),
      username: await secrets.getSecret(`${secretsPrefix}/database/username`),
      password: await secrets.getSecret(`${secretsPrefix}/database/password`)
    },
    jwt: {
      secret: await secrets.getSecret(`${secretsPrefix}/jwt/secret`),
      expiresIn: await secrets.getSecret(`${secretsPrefix}/jwt/expiresIn`)
    },
    aws: {
      region: process.env.AWS_REGION || 'us-east-1'
    },
    anthropic: {
      apiKey: await secrets.getSecret(`${secretsPrefix}/anthropic/api-key`)
    },
    stripe: {
      secretKey: await secrets.getSecret(`${secretsPrefix}/stripe/secret-key`),
      webhookSecret: await secrets.getSecret(`${secretsPrefix}/stripe/webhook-secret`)
    }
  };
}

module.exports = { loadConfig, secrets };
```

