## Secrets Rotation Strategy

### Automated Rotation

```javascript
// rotation.js
const secrets = new SecretManager();

class RotatingSecret {
  constructor(secretName, rotationInterval) {
    this.secretName = secretName;
    this.rotationInterval = rotationInterval;
    this.lastRotation = Date.now();
    this.currentValue = null;
  }

  async getValue() {
    // Check if rotation needed
    if (Date.now() - this.lastRotation > this.rotationInterval) {
      await this.rotate();
    }

    if (!this.currentValue) {
      this.currentValue = await secrets.getSecret(this.secretName);
    }

    return this.currentValue;
  }

  async rotate() {
    console.log(`Rotating secret: ${this.secretName}`);

    // 1. Get current secret
    const current = await secrets.getSecret(this.secretName);

    // 2. Generate new secret
    const newPassword = generateSecurePassword();

    // 3. Update in provider (e.g., database)
    await updateDatabasePassword(newPassword);

    // 4. Store in Secrets Manager
    await secrets.client.updateSecret({
      SecretId: this.secretName,
      SecretString: JSON.stringify({ ...current, password: newPassword })
    }).promise();

    // 5. Update local cache
    this.currentValue = newPassword;
    this.lastRotation = Date.now();

    console.log(`Secret rotated successfully: ${this.secretName}`);
  }
}

// Usage
const dbPassword = new RotatingSecret('myapp/production/database/password', 30 * 24 * 60 * 60 * 1000); // 30 days
