/**
 * Secure Configuration Management
 * 
 * This module handles loading and validating configuration/secrets from appropriate
 * sources based on the environment (dotenv for dev, Secrets Manager for prod).
 */

const path = require('path');
const AWS = require('aws-sdk');

// ============================================================================
// Environment Setup
// ============================================================================

const nodeEnv = process.env.NODE_ENV || 'development';
const isProduction = nodeEnv === 'production';
const isTest = nodeEnv === 'test';

// Load dotenv only in non-production environments
if (!isProduction && !isTest) {
  try {
    require('dotenv').config({
      path: path.join(__dirname, '.env')
    });
    console.log(`[Config] Loaded environment variables from .env`);
  } catch (err) {
    console.warn(`[Config] dotenv not available: ${err.message}`);
  }
}

// ============================================================================
// Secrets Manager (Production)
// ============================================================================

class SecretsManager {
  constructor() {
    if (!isProduction) {
      this.client = null;
      return;
    }

    const region = process.env.AWS_REGION || 'us-east-1';
    this.client = new AWS.SecretsManager({ region });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretId, options = {}) {
    // In non-production, use environment variables
    if (!isProduction) {
      return this.getSecretFromEnv(secretId);
    }

    const { forceRefresh = false } = options;
    const cacheKey = secretId;

    // Check cache first
    const cached = this.cache.get(cacheKey);
    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      console.log(`[Secrets] Using cached secret: ${secretId}`);
      return cached.value;
    }

    // Fetch from AWS Secrets Manager
    try {
      const data = await this.client
        .getSecretValue({ SecretId: secretId })
        .promise();

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = data.SecretBinary.toString('utf-8');
      }

      // Cache the secret
      this.cache.set(cacheKey, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[Secrets] Loaded secret: ${secretId}`);
      return secret;
    } catch (error) {
      console.error(`[Secrets] Failed to load secret ${secretId}:`, error.message);
      throw new Error(`Unable to retrieve secret: ${secretId}`);
    }
  }

  getSecretFromEnv(secretId) {
    // Map secret IDs to environment variables
    const secretMap = {
      'myapp/database': {
        url: process.env.DATABASE_URL,
        username: process.env.DB_USER,
        password: process.env.DB_PASSWORD,
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        name: process.env.DB_NAME
      },
      'myapp/jwt': {
        secret: process.env.JWT_SECRET,
        expiresIn: process.env.JWT_EXPIRES_IN || '1h'
      },
      'myapp/stripe': {
        secretKey: process.env.STRIPE_SECRET_KEY,
        webhookSecret: process.env.STRIPE_WEBHOOK_SECRET
      },
      'myapp/anthropic': {
        apiKey: process.env.ANTHROPIC_API_KEY
      },
      'myapp/aws': {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION
      }
    };

    if (!secretMap[secretId]) {
      return {};
    }

    return secretMap[secretId];
  }

  clearCache() {
    this.cache.clear();
    console.log('[Secrets] Cache cleared');
  }
}

// ============================================================================
// Configuration Loader
// ============================================================================

class Config {
  constructor() {
    this.secrets = new SecretsManager();
    this._config = null;
  }

  /**
   * Load all configuration
   */
  async load() {
    if (this._config) {
      return this._config;
    }

    const env = nodeEnv;
    const secretsPrefix = `myapp/${env}`;

    console.log(`[Config] Loading configuration for environment: ${env}`);

    try {
      const config = {
        env,
        server: await this.loadServerConfig(),
        database: await this.loadDatabaseConfig(secretsPrefix),
        jwt: await this.loadJWTConfig(secretsPrefix),
        stripe: await this.loadStripeConfig(secretsPrefix),
        anthropic: await this.loadAnthropicConfig(secretsPrefix),
        aws: await this.loadAWSConfig(),
        logging: this.loadLoggingConfig()
      };

      this._config = config;
      console.log('[Config] Configuration loaded successfully');
      return config;
    } catch (error) {
      console.error('[Config] Failed to load configuration:', error.message);
      throw error;
    }
  }

  async loadServerConfig() {
    return {
      port: parseInt(process.env.PORT) || 3000,
      host: process.env.HOST || '0.0.0.0',
      trustProxy: process.env.TRUST_PROXY === 'true',
      url: process.env.APP_URL || `http://localhost:${process.env.PORT || 3000}`
    };
  }

  async loadDatabaseConfig(secretsPrefix) {
    const secrets = await this.secrets.getSecret(`${secretsPrefix}/database`);

    return {
      // Support both URL format and individual parameters
      url: secrets.url || process.env.DATABASE_URL,
      host: secrets.host || process.env.DB_HOST || 'localhost',
      port: parseInt(secrets.port || process.env.DB_PORT) || 5432,
      database: secrets.name || secrets.database || process.env.DB_NAME || 'myapp',
      username: secrets.username || process.env.DB_USER || 'postgres',
      password: secrets.password || process.env.DB_PASSWORD,
      ssl: secrets.ssl !== false && isProduction,
      pool: {
        min: parseInt(secrets.poolMin || process.env.DB_POOL_MIN) || 2,
        max: parseInt(secrets.poolMax || process.env.DB_POOL_MAX) || 10,
        idleTimeoutMillis: 30000
      }
    };
  }

  async loadJWTConfig(secretsPrefix) {
    const secrets = await this.secrets.getSecret(`${secretsPrefix}/jwt`);

    const secret = secrets.secret || process.env.JWT_SECRET;

    if (!secret) {
      throw new Error('JWT_SECRET is required');
    }

    return {
      secret,
      expiresIn: secrets.expiresIn || process.env.JWT_EXPIRES_IN || '1h',
      algorithm: secrets.algorithm || 'HS256',
      issuer: secrets.issuer || process.env.JWT_ISSUER || 'myapp'
    };
  }

  async loadStripeConfig(secretsPrefix) {
    const secrets = await this.secrets.getSecret(`${secretsPrefix}/stripe`);

    return {
      secretKey: secrets.secretKey || process.env.STRIPE_SECRET_KEY,
      publishableKey: secrets.publishableKey || process.env.STRIPE_PUBLISHABLE_KEY,
      webhookSecret: secrets.webhookSecret || process.env.STRIPE_WEBHOOK_SECRET
    };
  }

  async loadAnthropicConfig(secretsPrefix) {
