    return {
      apiKey: secrets.apiKey || process.env.ANTHROPIC_API_KEY,
      baseUrl: secrets.baseUrl || 'https://api.anthropic.com',
      maxTokens: secrets.maxTokens || 4096,
      model: secrets.model || 'claude-3-opus-20240229'
    };
  }

  async loadAWSConfig() {
    return {
      region: process.env.AWS_REGION || 'us-east-1',
      // Note: Don't include credentials here
      // AWS SDK will handle credential chain automatically
      s3: {
        bucket: process.env.AWS_S3_BUCKET
      }
    };
  }

