    return {
      level: process.env.LOG_LEVEL || (isProduction ? 'info' : 'debug'),
      format: process.env.LOG_FORMAT || 'json'
    };
  }

  /**
   * Validate configuration
   */
  static validate(config) {
    const errors = [];

    // Required fields
    const required = {
      database: ['host', 'password'],
      jwt: ['secret'],
      server: ['port']
    };

    for (const [section, fields] of Object.entries(required)) {
      if (!config[section]) {
        errors.push(`Missing config section: ${section}`);
        continue;
      }

      for (const field of fields) {
        if (!config[section][field]) {
          errors.push(`Missing ${section}.${field}`);
        }
      }
    }

    // Validate JWT secret strength
    if (config.jwt && config.jwt.secret && config.jwt.secret.length < 32) {
      errors.push('JWT_SECRET must be at least 32 characters');
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }

    console.log('[Config] Configuration validated successfully');
  }

  /**
   * Get config value by path (dot notation)
   */
  get(path) {
    if (!this._config) {
      throw new Error('Configuration not loaded. Call load() first.');
    }

    return path.split('.').reduce((obj, key) => obj?.[key], this._config);
  }

  /**
   * Get entire config
   */
  getAll() {
    if (!this._config) {
      throw new Error('Configuration not loaded. Call load() first.');
    }
    return this._config;
  }

  /**
   * Clear config (useful for testing)
   */
  clear() {
    this._config = null;
    if (this.secrets.client) {
      this.secrets.clearCache();
    }
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

const config = new Config();

// Load config synchronously in production (fail fast), async in other environments
async function initializeConfig() {
  try {
    const loadedConfig = await config.load();
    Config.validate(loadedConfig);
    return loadedConfig;
  } catch (error) {
    console.error('[Config] Fatal: Failed to initialize configuration');
    console.error(error.message);
    throw error;
  }
}

// ============================================================================
// Environment Variable Validation
// ============================================================================

function validateEnvVars() {
  // These env vars should always be set
  const alwaysRequired = ['NODE_ENV'];

  // Dev/staging specific
  const devRequired = isProduction ? [] : [
    'JWT_SECRET'
  ];

  const allRequired = [...alwaysRequired, ...devRequired];
  const missing = allRequired.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Required environment variables missing: ${missing.join(', ')}`);
  }

  console.log('[Config] Environment variables validated');
}

// Run immediate validation
try {
  validateEnvVars();
} catch (error) {
  console.warn(`[Config] ${error.message}`);
  if (isProduction) {
    throw error;
  }
}

// ============================================================================
// Exports
// ============================================================================

module.exports = {
  config,
  initializeConfig,
  SecretsManager,
  Config,
  validateEnvVars
};

#!/usr/bin/env node

/**
 * Secret Detection Script
 * 
 * Scans the codebase for potential secrets that may have been accidentally committed.
 * Run this before committing or in CI/CD pipeline.
 */

const fs = require('fs');
const path = require('path');

// Patterns that might indicate secrets
const SECRET_PATTERNS = [
  // API Keys
  {
    name: 'API Key',
    pattern: /(?:api[_-]?key|apikey)\s*[:=]\s*['"]([a-zA-Z0-9_-]{20,})['"]/gi,
    severity: 'HIGH'
  },
  // AWS Keys
  {
    name: 'AWS Access Key',
    pattern: /(?:aws[_-]?access[_-]?key[_-]?id|access[_-]?key[_-]?id)\s*[:=]\s*['"]?(AKIA[0-9A-Z]{16})['"]?/gi,
    severity: 'CRITICAL'
  },
  {
    name: 'AWS Secret Key',
    pattern: /(?:aws[_-]?secret[_-]?access[_-]?key|secret[_-]?access[_-]?key)\s*[:=]\s*['"]([a-zA-Z0-9/+]{40})['"]/gi,
    severity: 'CRITICAL'
  },
  // Database URLs
  {
    name: 'Database URL',
    pattern: /(?:database[_-]?url|database_url|db[_-]?url)\s*[:=]\s*['"]([a-z]+:\/\/[^\s'"@]+:[^\s'"@]+@[^\s'"]+)['"]/gi,
    severity: 'HIGH'
  },
  // Passwords
  {
    name: 'Password Assignment',
    pattern: /(?:password|passwd|pwd)\s*[:=]\s*['"]([^'"]{8,})['"]/gi,
    severity: 'MEDIUM'
  },
  // JWT Secrets
  {
    name: 'JWT Secret',
    pattern: /(?:jwt[_-]?secret|secret)\s*[:=]\s*['"]([a-zA-Z0-9_-]{32,})['"]/gi,
    severity: 'HIGH'
  },
  // Private Keys
  {
    name: 'Private Key',
    pattern: /-----BEGIN(?: (RSA|EC|DSA|OPENSSH|PGP))? PRIVATE KEY-----/g,
    severity: 'CRITICAL'
  },
  // Tokens
  {
    name: 'Bearer Token',
    pattern: /(?:bearer[_-]?token|token)\s*[:=]\s*['"]([a-zA-Z0-9_-]{20,})['"]/gi,
    severity: 'HIGH'
  },
  // Stripe Keys
  {
    name: 'Stripe Key',
    pattern: /(?:stripe[_-]?(?:secret|publishable)[_-]?key)\s*[:=]\s*['"](sk_(?:live|test)_[a-zA-Z0-9]{24,})['"]/gi,
    severity: 'HIGH'
  },
  // GitHub Tokens
  {
    name: 'GitHub Token',
    pattern: /(?:github[_-]?token|ghp_|gho_|ghu_|ghs_|ghr_)[\w]{36}/gi,
    severity: 'HIGH'
  }
];

// Files and directories to exclude
const EXCLUDE_PATTERNS = [
  /^node_modules/,
  /\.git/,
  /^dist/,
  /^build/,
  /\.env$/,
  /\.env\./,
  /coverage/,
  /-lock\.json$/,
  /yarn\.lock$/,
  /\.min\.js$/,
  /^\.vscode/,
  /^\.idea/,
  /check-secrets\.js$/,
  /SECRETS_ANALYSIS\.md$/
];

// Known false positives (canary values, test fixtures)
const FALSE_POSITIVES = [
  /canary/i,
  /test[-_]?value/i,
  /example/i,
  /[^a-zA-Z]placeholder[^a-zA-Z]/i,
  /xxx/i,
  /changelog/i,
  /readme/i,
  /SECUR/i,
  /ANALYSIS/i
];

function shouldExclude(filePath) {
  return EXCLUDE_PATTERNS.some(pattern => pattern.test(filePath));
}

function isFalsePositive(match, filePath) {
  return FALSE_POSITIVES.some(pattern => 
    pattern.test(match) || pattern.test(filePath)
  );
}

function scanFile(filePath) {
  const findings = [];

  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');

    SECRET_PATTERNS.forEach(rule => {
      let match;
      const regex = new RegExp(rule.pattern.source, rule.pattern.flags);

      while ((match = regex.exec(content)) !== null) {
        const matchedText = match[1] || match[0];
        const lineNumber = content.substring(0, match.index).split('\n').length;
        const lineContent = lines[lineNumber - 1].trim();

        // Skip false positives
        if (isFalsePositive(matchedText, filePath)) {
          continue;
        }

        findings.push({
          type: rule.name,
          severity: rule.severity,
          file: filePath,
          line: lineNumber,
          content: lineContent,
          match: matchedText
        });
      }
    });
  } catch (error) {
    // Skip files that can't be read as text
  }

  return findings;
}

function scanDirectory(dir, findings = []) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (shouldExclude(fullPath)) {
      continue;
    }

    if (entry.isDirectory()) {
      scanDirectory(fullPath, findings);
    } else if (entry.isFile()) {
      const fileFindings = scanFile(fullPath);
      findings.push(...fileFindings);
    }
  }

  return findings;
}

function groupBySeverity(findings) {
  return {
    CRITICAL: findings.filter(f => f.severity === 'CRITICAL'),
    HIGH: findings.filter(f => f.severity === 'HIGH'),
    MEDIUM: findings.filter(f => f.severity === 'MEDIUM'),
    LOW: findings.filter(f => f.severity === 'LOW')
  };
}

function printFindings(findings) {
  const grouped = groupBySeverity(findings);
  const severityOrder = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
  const colors = {
    CRITICAL: '\x1b[31m', // red
    HIGH: '\x1b[33m',    // yellow
    MEDIUM: '\x1b[36m',  // cyan
    LOW: '\x1b[37m'      // white
  };
  const reset = '\x1b[0m';

  let totalFindings = 0;

  for (const severity of severityOrder) {
    const items = grouped[severity];
    if (items.length === 0) continue;

    console.log(`\n${colors[severity]}═══════════════════════════════════════${reset}`);
    console.log(`${colors[severity]}${severity} SECRETS FOUND: ${items.length}${reset}`);
    console.log(`${colors[severity]}═══════════════════════════════════════${reset}\n`);

    items.forEach((finding, i) => {
      console.log(`${i + 1}. ${finding.type}`);
      console.log(`   File: ${finding.file}`);
      console.log(`   Line: ${finding.line}`);
      console.log(`   Content: ${finding.content.substring(0, 100)}...`);
      console.log(`   Match: ${finding.match.substring(0, 50)}...`);
      console.log('');
    });

    totalFindings += items.length;
  }

  return totalFindings;
}

function main() {
  const rootDir = process.argv[2] || '.';

  console.log('🔍 Scanning for potential secrets...');
  console.log(`📁 Directory: ${path.resolve(rootDir)}\n`);

  const findings = scanDirectory(rootDir);

  if (findings.length === 0) {
    console.log('✅ No secrets found!');
    console.log('\nRemember to:');
    console.log('  • Never commit .env files');
    console.log('  • Use environment variables for configuration');
    console.log('  • Store secrets in a secrets manager in production');
    process.exit(0);
  }

  const total = printFindings(findings);

  console.log(`\n${'='.repeat(50)}`);
  console.log(`Total findings: ${total}`);
  console.log(`${'='.repeat(50)}`);

  if (findings.some(f => f.severity === 'CRITICAL')) {
    console.log('\n🚨 CRITICAL secrets found! Do not commit this code!');
    console.log('   Remove sensitive data and use secrets management.');
    process.exit(1);
  } else if (findings.some(f => f.severity === 'HIGH')) {
    console.log('\n⚠️  HIGH severity secrets found!');
    console.log('   Review and remove before committing.');
    process.exit(1);
  } else {
    console.log('\n⚠️  Some potential secrets found.');
    console.log('   Review them to confirm they are not sensitive.');
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = { scanDirectory, SECRET_PATTERNS, EXCLUDE_PATTERNS };

