```javascript
// package.json
{
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.450.0"
  }
}

// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // Use IAM role for auth - NEVER hardcode credentials
    });
    this.cache = {};
    this.cacheExpiry = {};
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache[secretName] && 
        Date.now() < this.cacheExpiry[secretName]) {
      return this.cache[secretName];
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString)
        : null;

      // Cache for 5 minutes (reduces API calls, balances security)
      this.cache[secretName] = secret;
      this.cacheExpiry[secretName] = Date.now() + (5 * 60 * 1000);

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }
}

module.exports = new SecretsManager();
```

