/**
 * Secure Secrets Management
 * 
 * This module loads secrets in the following priority order:
 * 1. Environment variables (highest priority)
 * 2. Secrets manager (AWS Secrets Manager, HashiCorp Vault, etc.)
 * 3. .env file (lowest priority - development only)
 * 
 * NEVER commit actual secrets to version control.
 */

const fs = require('fs');
const path = require('path');

// Don't load .env files in production
const isProduction = process.env.NODE_ENV === 'production';
const isTest = process.env.NODE_ENV === 'test';

// Required secrets validation
const REQUIRED_SECRETS = [
  // Add secrets that must be present in production
  // 'DATABASE_URL',
  // 'JWT_SECRET',
];

function loadSecrets() {
  const secrets = {};

  // 1. Load from environment variables (always available)
  Object.keys(process.env).forEach(key => {
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('TOKEN') || key.includes('PASSWORD')) {
      secrets[key] = process.env[key];
    }
  });

  // 2. Try to load from a secrets manager in production
  if (isProduction) {
    const secretsManagerSecrets = loadFromSecretsManager();
    Object.assign(secrets, secretsManagerSecrets);
  }

  // 3. Load from .env file in non-production environments
  if (!isProduction) {
    const envSecrets = loadFromEnvFile();
    Object.assign(secrets, envSecrets);
  }

  // 4. Validate required secrets are present
  validateRequiredSecrets(secrets);

  return secrets;
}

function loadFromSecretsManager() {
  const secrets = {};
  const secretsProvider = process.env.SECRETS_PROVIDER || 'none';

  try {
    switch (secretsProvider) {
      case 'aws':
        Object.assign(secrets, loadFromAWSSecretsManager());
        break;
      case 'vault':
        Object.assign(secrets, loadFromVault());
        break;
      case 'gcp':
        Object.assign(secrets, loadFromGCPSecretManager());
        break;
      default:
        console.warn('No secrets manager configured, using environment variables only');
    }
  } catch (error) {
    console.error('Error loading from secrets manager:', error.message);
    throw new Error('Failed to load secrets from secrets manager');
  }

  return secrets;
}

function loadFromAWSSecretsManager() {
  // Lazy load AWS SDK
  try {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    const secretName = process.env.AWS_SECRET_NAME;
    if (!secretName) {
      return {};
    }

    const response = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }

    return {};
  } catch (error) {
    if (error.name === 'ExportsNotInitialized' || error.code === 'MODULE_NOT_FOUND') {
      console.warn('AWS SDK not installed, secrets manager unavailable');
      return {};
    }
    throw error;
  }
}

function loadFromVault() {
  // Implementation for HashiCorp Vault
  // This is a placeholder - implement based on your Vault configuration
  try {
    const { Vault } = require('node-vault');

    const vault = Vault({
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN,
    });

    const path = process.env.VAULT_SECRET_PATH || 'secret/data/app';
    const result = await vault.read(path);

    return result.data.data;
  } catch (error) {
    if (error.code === 'MODULE_NOT_FOUND') {
      console.warn('Vault client not installed');
      return {};
    }
    throw error;
  }
}

function loadFromGCPSecretManager() {
  // Implementation for GCP Secret Manager
  // Placeholder - implement based on your GCP configuration
  try {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

    const client = new SecretManagerServiceClient();
    const projectId = process.env.GCP_PROJECT_ID;
    const secretNames = process.env.GCP_SECRET_NAMES?.split(',') || [];

    const secrets = {};

    for (const name of secretNames) {
      const [version] = await client.accessSecretVersion({
        name: `projects/${projectId}/secrets/${name}/versions/latest`,
      });
      secrets[name] = version.payload.data.toString();
    }

    return secrets;
  } catch (error) {
    if (error.code === 'MODULE_NOT_FOUND') {
      console.warn('GCP Secret Manager client not installed');
      return {};
    }
    throw error;
  }
}

function loadFromEnvFile() {
  const secrets = {};
  const envFiles = ['.env.local', '.env.test', '.env.development', '.env'];

  for (const envFile of envFiles) {
    const envPath = path.join(process.cwd(), envFile);

    if (fs.existsSync(envPath)) {
      console.warn(`Loading secrets from ${envFile} - DO NOT COMMIT THIS FILE!`);

      const content = fs.readFileSync(envPath, 'utf-8');
      const lines = content.split('\n');

      for (const line of lines) {
        const trimmed = line.trim();

        // Skip empty lines and comments
        if (!trimmed || trimmed.startsWith('#')) {
          continue;
        }

        // Parse KEY=VALUE
        const separatorIndex = trimmed.indexOf('=');
        if (separatorIndex > 0) {
          const key = trimmed.slice(0, separatorIndex).trim();
          const value = trimmed.slice(separatorIndex + 1).trim()
            .replace(/^['"]|['"]$/g, ''); // Remove quotes

          if (key && value) {
            secrets[key] = value;
          }
        }
      }

      break; // Load first available file only
    }
  }

  return secrets;
}

function validateRequiredSecrets(secrets) {
  if (isProduction) {
    const missing = REQUIRED_SECRETS.filter(secret => !secrets[secret]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets in production: ${missing.join(', ')}`
      );
    }
  }
}

/**
 * Get a secret value
 * @param {string} key - Secret key name
 * @param {string} defaultValue - Default value if secret not found (optional)
 * @returns {string|undefined} Secret value or default
 */
function getSecret(key, defaultValue) {
  // Check environment variable first (runtime override)
  if (process.env[key] !== undefined) {
    return process.env[key];
  }

  // Check loaded secrets
  if (secretsCache[key] !== undefined) {
    return secretsCache[key];
  }

  // Return default if provided
  return defaultValue;
}

/**
 * Get all secrets (for debugging - never use in production)
 * @returns {object} All loaded secrets
 */
function getAllSecrets() {
  if (isProduction) {
    throw new Error('getAllSecrets() should never be called in production');
  }

  return { ...secretsCache };
}

// Cache for loaded secrets
let secretsCache = null;

// Load secrets on module import
if (!secretsCache) {
  secretsCache = loadSecrets();
}

module.exports = {
  getSecret,
  getAllSecrets,
  loadSecrets,
  validateRequiredSecrets,
};

