#### 5. **Use Environment-Specific Loading**

```javascript
// config/env.js
const path = require('path');
const dotenv = require('dotenv');

const NODE_ENV = process.env.NODE_ENV || 'development';

// Load environment-specific .env file
const envFile = `.env.${NODE_ENV}`;
const envPath = path.resolve(process.cwd(), envFile);

try {
  const result = dotenv.config({ path: envPath });
  if (result.error) {
    throw result.error;
  }
  console.log(`✅ Loaded environment from ${envFile}`);
} catch (error) {
  // Try default .env file
  try {
    dotenv.config();
    console.log(`✅ Loaded environment from .env`);
  } catch (err) {
    if (NODE_ENV === 'production') {
      console.error('❌ Failed to load environment file in production');
      console.error('   Secrets should be provided via environment variables');
      throw err;
    }
    console.warn(`⚠️  No .env file found, using process.env only`);
  }
}
