### **Phase 4: Secrets Manager Integration**

#### 6. **Production: Use AWS Secrets Manager**

```javascript
// config/aws-secrets-manager.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.client = new AWS.SecretsManager({ region });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        return cached.value;
      }
    }

    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secret;
      if (data.SecretString) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.code === 'DecryptionFailureException') {
        throw new Error('Secrets Manager cannot decrypt the secret');
      } else if (error.code === 'AccessDeniedException') {
        throw new Error('Access denied to secret in Secrets Manager');
      }
      throw error;
    }
  }

  async loadAllSecrets(secretMappings) {
    const secrets = {};
    for (const [envVar, secretName] of Object.entries(secretMappings)) {
      try {
        secrets[envVar] = await this.getSecret(secretName);
      } catch (error) {
        console.error(`Failed to load secret ${secretName}:`, error.message);
        throw error;
      }
    }
    return secrets;
  }
}

module.exports = SecretsManager;
```

**Usage in Production:**

```javascript
// app.js - Production version
if (process.env.NODE_ENV === 'production') {
  const SecretsManager = require('./config/aws-secrets-manager');
  const secretsManager = new SecretsManager();

  const secretMappings = {
    DATABASE_URL: 'prod/app/database',
    AWS_ACCESS_KEY_ID: 'prod/app/aws-access-key',
    AWS_SECRET_ACCESS_KEY: 'prod/app/aws-secret-key',
    ANTHROPIC_API_KEY: 'prod/app/anthropic-api-key',
    STRIPE_SECRET_KEY: 'prod/app/stripe-secret-key',
    JWT_SECRET: 'prod/app/jwt-secret',
    SESSION_SECRET: 'prod/app/session-secret'
  };

  secretsManager.loadAllSecrets(secretMappings)
    .then(secrets => {
      // Merge into process.env
      Object.assign(process.env, secrets);
      startServer();
    })
    .catch(err => {
      console.error('Failed to load secrets from AWS Secrets Manager:', err);
      process.exit(1);
    });
} else {
  startServer();
}
```

