### **Phase 5: Runtime Secret Protection**

#### 8. **Prevent Secrets from Leaking in Logs**

```javascript
// utils/sanitize.js
const sensitiveKeys = [
  'password', 'secret', 'token', 'key', 'authorization',
  'database_url', 'aws_secret_access_key', 'stripe_secret_key',
  'anthropic_api_key', 'jwt_secret', 'session_secret'
];

function sanitizeLog(data) {
  const dataStr = JSON.stringify(data);
  const sensitivePattern = new RegExp(
    `("(${sensitiveKeys.join('|')})"\\s*:\\s*")[^"]+`, 'gi'
  );

  return dataStr.replace(sensitivePattern, '$1[REDACTED]');
}

// Override console methods in production
if (process.env.NODE_ENV === 'production') {
  const originalLog = console.log;
  const originalError = console.error;

  console.log = (...args) => {
    const sanitized = args.map(arg => {
      return typeof arg === 'object' ? sanitizeLog(arg) : arg;
    });
    originalLog.apply(console, sanitized);
  };

  console.error = (...args) => {
    const sanitized = args.map(arg => {
      return typeof arg === 'object' ? sanitizeLog(arg) : arg;
    });
    originalError.apply(console, sanitized);
  };
}
```

#### 9. **Prevent Secrets in Error Responses**

```javascript
// middleware/no-secrets-in-response.js
app.use((err, req, res, next) => {
  const sanitizedError = {
    message: err.message,
    requestId: req.id
  };

  // Remove stack traces in production
  if (process.env.NODE_ENV !== 'production') {
    sanitizedError.stack = err.stack;
  }

  // Check for secrets in error message
  const hasSecret = sensitiveKeys.some(key => 
    err.message.toLowerCase().includes(key)
  );

  if (hasSecret) {
    sanitizedError.message = 'Internal Server Error';
  }

  res.status(err.status || 500).json({
    error: sanitizedError
  });
});
```

