const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '../.env') });

/**
 * Secure Secrets Manager
 * 
 * This module handles loading and validating secrets from multiple sources:
 * 1. Environment variables (highest priority)
 * 2. Secure secrets manager (AWS Parameter Store / Secrets Manager)
 * 
 * NEVER commit actual secrets to version control!
 */

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.ttl = parseInt(process.env.SECRETS_CACHE_TTL || '300000'); // 5 minutes default
    this.initialized = false;
  }

  /**
   * Generate a secure random secret
   */
  static generateSecret(length = 32) {
    const crypto = require('crypto');
    return crypto.randomBytes(length).toString('base64');
  }

  /**
   * Generate a hex secret (32 bytes = 64 hex chars)
   */
  static generateHexSecret(byteLength = 32) {
    const crypto = require('crypto');
    return crypto.randomBytes(byteLength).toString('hex');
  }

  /**
   * Get a secret from cache or environment
   */
  async get(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.timestamp > Date.now()) {
      process.env.NODE_ENV !== 'production' && 
        console.log(`[Secrets] Retrieved from cache: ${secretName}`);
      return cached.value;
    }

    // Try environment variable first (highest priority)
    const envValue = process.env[secretName];
    if (envValue) {
      this.cache.set(secretName, {
        value: envValue,
        timestamp: Date.now() + this.ttl
      });
      process.env.NODE_ENV !== 'production' && 
        console.log(`[Secrets] Retrieved from environment: ${secretName}`);
      return envValue;
    }

    // Note:AWS Secrets Manager integration would go here
    // For now, we'll throw an error if secret not found
    throw new Error(`Secret not found: ${secretName}. Please set ${secretName} in environment variables.`);
  }

  /**
   * Get multiple secrets at once
   */
  async getMany(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.get(name);
    }
    return secrets;
  }

  /**
   * Validate that all required secrets are present and secure
   */
  async validateRequired(requirements = []) {
    const errors = [];
    const warnings = [];

    for (const req of requirements) {
      const { name, minLength, maxLength, pattern, required = true } = req;

      try {
        const value = await this.get(name);

        // Check minimum length
        if (minLength && value.length < minLength) {
          errors.push(`${name}: Too short (min ${minLength} chars, got ${value.length})`);
        }

        // Check maximum length
        if (maxLength && value.length > maxLength) {
          warnings.push(`${name}: Exceeds recommended max length of ${maxLength}`);
        }

        // Check pattern match
        if (pattern && !pattern.test(value)) {
          errors.push(`${name}: Invalid format`);
        }

        // Check for placeholder/example values
        const placeholders = [
          'CHANGE_THIS', 'REPLACE_ME', 'YOUR_SECRET', 'EXAMPLE',
          'your-secret-here', 'secret-key-here', 'placeholder',
          'your-api-key', 'your-password', 'canary'
        ];

        if (placeholders.some(p => 
          value.toLowerCase().includes(p.toLowerCase())
        )) {
          errors.push(`${name}: Contains placeholder value - must use real secret`);
        }

        // Check for common weak secrets
        const weakPatterns = [
          /^password$/i, /^secret$/i, /^admin$/i,
          /^123456$/, /^qwerty$/, /^abc123$/,
          /^(test|dev|staging|demo)\*?$/i
        ];

        if (weakPatterns.some(p => p.test(value))) {
          errors.push(`${name}: Contains weak/obvious value`);
        }

        // Check entropy for high-value secrets
        if (['JWT_SECRET', 'SESSION_SECRET', 'ENCRYPTION_KEY'].includes(name)) {
          const uniqueChars = new Set(value).size;
          const entropy = uniqueChars / value.length;

          if (entropy < 0.5) {
            warnings.push(
              `${name}: Low entropy detected (${(entropy * 100).toFixed(1)}% unique chars). Use a stronger secret.`
            );
          }
        }

        // Warn if secret appears in known leaked passwords lists
        // In production, you'd integrate with HaveIBeenPwned API
        process.env.NODE_ENV !== 'test' && 
          console.log(`✅ ${name}: Validated`);

      } catch (error) {
        if (required) {
          errors.push(`${name}: ${error.message}`);
        } else {
          warnings.push(`${name}: Optional secret not set (${error.message})`);
        }
      }
    }

    return { errors, warnings };
  }

  /**
   * Validate all required secrets for this application
   */
  async validateAll() {
    const requirements = [
      // Authentication
      { name: 'JWT_SECRET', minLength: 32, required: true },
      { name: 'SESSION_SECRET', minLength: 32, required: true },

      // Database
      { name: 'DATABASE_URL', pattern: /^postgresql:\/\//i, required: true },

      // Encryption (optional but recommended)
      { name: 'ENCRYPTION_KEY', minLength: 32, required: false },

      // External API keys (if using)
      { name: 'AWS_ACCESS_KEY_ID', pattern: /^AKIA[0-9A-Z]{16}$/, required: false },
      { name: 'AWS_SECRET_ACCESS_KEY', minLength: 40, required: false },
      { name: 'STRIPE_SECRET_KEY', pattern: /^sk_(test|live)_/, required: false },
    ];

    const { errors, warnings } = await this.validateRequired(requirements);

    if (errors.length > 0) {
      console.error('\n❌ SECRETS VALIDATION FAILED:\n');
      errors.forEach(err => console.error(`  ❌ ${err}`));
      throw new Error(`Secrets validation failed with ${errors.length} error(s)`);
    }

    if (warnings.length > 0) {
      console.warn('\n⚠️  SECRETS WARNINGS:\n');
      warnings.forEach(warn => console.warn(`  ⚠️  ${warn}`));
    }

    console.log('\n✅ All secrets validated successfully!\n');
    this.initialized = true;
    return true;
  }

  /**
   * Clear the secret cache
   */
  clearCache() {
    this.cache.clear();
    console.log('[Secrets] Cache cleared');
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    return {
      size: this.cache.size,
      keys: Array.from(this.cache.keys()),
      ttl: this.ttl
    };
  }
}

